    requiredIngredients: [getIng('beyaz_peynir'), getIng('biber'), getIng('domates'), getIng('kasar'), getIng('pastirma'), getIng('siviyag'), getIng('yufka')],
    steps: [
        "1. İlk olarak paçanga böreğinin iç harcı hazırlanır.Biberler küçük küçük doğranarak az sıvı yağda sotelenir ve derin bir kap içerisine alınır. Dilerseniz çiğden de koyabilirsiniz ama ben 1-2 dakika önceden pişirmeyi tercih ediyorum. Biberler biraz soğuduktan sonra kabuğu soyulan ve küp küp doğranan domatesler, kaşar peyniri ve pastırmalar eklenip karıştırılarak iç harcı hazırlanır.",
        "2. Yufka ile börekler sarılır.Yufka büyüklüğüne göre 6 veya 8 üçgen parçaya bölünür. Her parçaya iç harcından bolca yerleştirilerek sigara böreği sarar gibi fakat daha irice sarılır.",
        "3. Hazırlanan paçanga börekleri kızartılır.Hazırlanan börekler bol sıvı yağda kızartılır. Sıcağıyla fazla bekletmeden servis yapmanızı öneririm. Afiyet olsun."
    ],
    chefTip: "Paçanga Böreği Nasıl Yapılır? hazırlarken malzemelerin taze olması ve pişerken kısık ateşte demlenmesi lezzeti iki katına çıkarır! 💡",
  ),
  Recipe(
    id: "r_10",
    title: "Et Sote Yapılışı",
    emoji: "🥗",
    imageUrl: "https://i.nefisyemektarifleri.com/2020/06/18/et-sote-yapilisi.jpg",
    prepTimeMinutes: 45,
    difficultyStars: 3,
    calories: 347,
    mealType: MealTypeFilter.mainCourse,
    ingredientsText: ["• 600g sotelik dana eti", "• 2 yemek kaşığı zeytinyağı ya da ayçiçek yağı", "• 1 adet soğan", "• 2 adet yeşil biber", "• 1 adet kapya biber", "• 1-2 adet domates", "• 1 yemek kaşığı domates salçası", "• 1 su bardağı sıcak su", "• Tuz", "• Karabiber", "• Kırmızı pul biber"],
    requiredIngredients: [getIng('biber'), getIng('domates'), getIng('karabiber'), getIng('pulbiber'), getIng('salca'), getIng('sogan'), getIng('tuz'), getIng('zeytinyagi')],
    steps: [
        "1. Dana etini sotelik olacak şekilde doğrayın. Çok büyük olmasına gerek yok küçük küçük doğrayabilirsiniz.",
        "2. Domateslerin kabuklarını soyup küp küp doğrayın.",
        "3. Biberlerin içlerini temizleyip istediğiniz boyutta doğrayın, çok küçük doğrarsanız etler pişene kadar eriyecektir bu nedenle biraz büyük doğrayabilirsiniz.",
        "4. Son olarak soğanı da soyarak yemeklik doğrayın. Ön hazırlığımız tamam şimdi pişirmeye geçebiliriz.",
        "5. Uygun bir tencereyi alalım. Derince bir tavada da yapabilirsiniz ama kapaklı olması önemli. Yağımızı tencereye alarak kızdıralım.",
        "6. Etleri tencereye ekleyerek etraflarını mühürleyene kadar yüksek ateşte karıştıralım.",
        "7. Hafif suyunu bırakırsa etlerimiz kapağını kapatarak suyunu çekene kadar pişirelim bu aşamada ocağı biraz kısabilirsiniz.",
        "8. Suyunu çeken etlerimize soğan ve biberleri ilave edelim. Karıştırarak kapağını kapatalım. Sebzeler diriliğini kaybedene kadar soteleyelim.",
        "9. Daha sonra domatesleri ve salçayı ilave edelim. Güzelce kavuralım ve tencerenin kapağını kapatarak orta ateşte pişirmeye devam edelim.",
        "10. Domateslerimiz de kavrulduktan sonra sıcak suyu (sıcak olması çok önemli) ve dilediğiniz baharatları,, tuzu ekleyerek tencerenin kapağını kapatalım. Etlerimiz yumuşacık pişene kadar pişirmeye devam edelim."
    ],
    chefTip: "Et Sote Yapılışı hazırlarken malzemelerin taze olması ve pişerken kısık ateşte demlenmesi lezzeti iki katına çıkarır! 💡",
  ),
  Recipe(
    id: "r_11",
    title: "Kahvaltılık Pratik Poğaça Tarifi",
    emoji: "🥐",
    imageUrl: "https://i.nefisyemektarifleri.com/2020/11/17/kahvaltilik-pratik-pogaca-tarifi-7.jpg",
    prepTimeMinutes: 30,
    difficultyStars: 2,
    calories: 313,
    mealType: MealTypeFilter.breakfast,
    ingredientsText: ["• Hamuru İçin;", "• 1 paket yaş maya", "• 4 yemek kaşığı şeker", "• 1 su bardağı ılık su", "• 1 su bardağı ılık süt", "• 1 su bardağı sıvı yağ", "• 1 adet yumurta", "• 1,5 tatlı kaşığı tuz", "• 7 su bardağı un", "• Üzeri için;", "• Yumurta sarısı", "• Susam"],
    requiredIngredients: [getIng('seker'), getIng('siviyag'), getIng('sut'), getIng('tuz'), getIng('un'), getIng('yumurta')],
    steps: [
        "1. Yoğurma kabına ılık su, ılık süt, yaş maya ve şekeri alıp çırpıcı ile karıştırarak mayanın erimesini sağlayalım. Mayanın daha iyi kabarması için, su ve süt karışınca, el yakmayacak düzeyde ılık olması gerekiyor.",
        "2. Üzerini streç film ile örtelim ve 10 dakika bekletelim.",
        "3. Ardından sıvı yağ, yumurta ve tuzuda ekleyerek karıştıralım.",
        "4. Unu azar azar ekleyip yoğurmaya başlayalım. Önemli olan unu az miktarlarda ekleyerek, yavaş yavaş iyice yoğurmak.",
        "5. Hamurumuzu unladığımız tezgahın üzerine alarak bir süre daha yoğuralım.",
        "6. Yoğurduğumuz hamuru tekrar yoğurma kabına alarak üzerini streçleyelim ve 1 saat kadar dinlenmeye bırakalım.",
        "7. Mayalanan hamurumuzun üzerini açıp bir kaç kez daha yoğurarak havasını çıkartalım.",
        "8. Ardından yumurta büyüklüğünde parçalar koparıp, elimizde yuvarlayalım ve  yağlı kağıt serilmiş tepsiye dizelim.",
        "9. Üzerine yumurta sarısı sürülüp, susam serptikten sonra 20 dakika kadar daha bekletelim.",
        "10. Daha sonra 180 derece fırında pişmeye bırakalım. Pişme süresi fırına göre değişebilir ama 20-25 dakika kadar bir sürede pişecektir. Ben bu ölçülerle 16 adet poğaça elde ettim.",
        "11. Puf puf kabaran, yumuşacık poğaçalarımız hazır. İster kahvaltılarda ekmek yerine yapabilirsiniz ya da çocuklar için arasına peynir, domates gibi kahvaltılıklar ekleyerek de, sandviç gibi servis edebilirsiniz. Mini mini sandviçler hazırlayabileceğiniz, kolay ve lezzetli poğaça tarifimizi çok beğeneceksiniz. Arasına arzunuza söre malzemelerle sandviçler hazırlayabileceğiz, kahvaltılık poğaça tarifini mutlaka denemenizi tavsiye ederim."
    ],
    chefTip: "Kahvaltılık Pratik Poğaça Tarifi hazırlarken malzemelerin taze olması ve pişerken kısık ateşte demlenmesi lezzeti iki katına çıkarır! 💡",
  ),
  Recipe(
