    title: "Nefis Waffle Tarifi (videolu)",
    emoji: "🧁",
    imageUrl: "https://i.nefisyemektarifleri.com/2021/09/21/nefis-waffle-tarifi.jpg",
    prepTimeMinutes: 10,
    difficultyStars: 1,
    calories: 267,
    mealType: MealTypeFilter.dessert,
    ingredientsText: ["• Waffle hamuru için;", "• 2 adet yumurta", "• 4 yemek kaşığı toz şeker", "• 1 su bardağı süt", "• 1/4 (çeyrek) su bardağı sıvı yağ", "• 1 paket vanilya", "• 1 paket kabartma tozu", "• Bir çimdik tuz", "• 2 su bardağı un", "• üzeri için;", "• çilek", "• kivi", "• muz", "• çikolata", "• fındık kırığı", "• toz fıstık"],
    requiredIngredients: [getIng('cikolata'), getIng('findik'), getIng('fistik'), getIng('seker'), getIng('siviyag'), getIng('sut'), getIng('tuz'), getIng('un'), getIng('vanilya'), getIng('yumurta')],
    steps: [
        "1. Waffle hamuru yapmak için; öncelikle yumurta ve şekeri iyice köpürünceye kadar çırpalım.",
        "2. Süt, sıvı yağ, tuz, kabartma tozu, vanilya ve unu ekleyip tekrar çırpalım. Waffle hamur hazır, pişirme işlemine geçebiliriz.",
        "3. Waffle makinesini ısıtıp 1 kepçe kadar hamuru makineye boşaltalım. Kapağını kapatıp pişmeye bırakalım. Pişirme işlemi kullandığınız waffle makinesine göre farklılık gösterebilir. Burada makinenizin kullanım kılavuzunu dikkate almanızı öneririm.",
        "4. Waffle hamuru pişerken meyvelerimizi dilimleyelim. Mevsimine göre hangi meyveyi kullanacağınızı kendiniz seçebilirsiniz. Ben en çok tercih edilen çilek muz ve kivi ile hazırlayacağım.",
        "5. Pişen waffle hamuru üzerine önce çikolatamızı sürelim. Üzerine istediğimiz meyveleri dizelim. Ardından fındık kırıkları ve fıstıkla süsleyelim. Waffle servise hazır. Şimdiden afiyet olsun :)"
    ],
    chefTip: "Nefis Waffle Tarifi (videolu) hazırlarken malzemelerin taze olması ve pişerken kısık ateşte demlenmesi lezzeti iki katına çıkarır! 💡",
  ),
  Recipe(
    id: "r_13",
    title: "İç Pilavlı Tavuk Dolması Nasıl Yapılır?",
    emoji: "🥗",
    imageUrl: "https://i.nefisyemektarifleri.com/2022/12/29/ic-pilavli-tavuk-dolmasi-nasil-yapilir-14.jpg",
    prepTimeMinutes: 35,
    difficultyStars: 2,
    calories: 278,
    mealType: MealTypeFilter.mainCourse,
    ingredientsText: ["• 1 adet bütün tavuk", "• 1 tatlı kaşığı un", "• 2-3 defne yaprağı", "• Limon dilimleri", "• Sosu için:", "• 1 tatlı kaşığı yoğurt", "• 1 tatlı kaşığı domates salçası", "• 2 yemek kaşığı sıvı yağ", "• 1 çay kaşığı toz kırmızı biber", "• Yarım tatlı kaşığı tuz", "• Pilavı için:", "• 2 su bardağı pilavlık pirinç", "• 2 yemek kaşığı tereyağı", "• Yarım çay bardağı dolmalık fıstık", "• Yarım çay bardağı kuş üzümü", "• 2 su bardağı sıcak su (400 ml)", "• 1 çay bardağı sıcak su (sonradan ekleniyor)", "• 1 tatlı kaşığı tuz", "• 1 çay kaşığı tarçın", "• 1 çay kaşığı karabiber", "• Garnitür olarak:", "• 2 adet patates", "• 2 adet havuç", "• Arpacık soğan"],
    requiredIngredients: [getIng('biber'), getIng('domates'), getIng('fistik'), getIng('havuc'), getIng('karabiber'), getIng('limon'), getIng('patates'), getIng('pirinc'), getIng('salca'), getIng('siviyag'), getIng('sogan'), getIng('tavuk'), getIng('tereyagi'), getIng('tuz'), getIng('un'), getIng('yogurt')],
    steps: [
        "1. Öncelikle iç pilavını hazırlamak için pilavlık pirinçler bir kaba alınır.",
        "2. Üzerini geçecek kadar ılık su ve tuz eklenerek 20 dakika bekletilir. Daha sonra bol su ile yıkanarak pişirme aşamasına geçilir.",
        "3. Pilavı pişirmek için öncelikle pilav tenceresine tereyağı ve sıvı yağ alınır. Ben tereyağı ve sıvı yağı karışık kullanıyorum, çünkü hem tereyağının lezzetini seviyorum, hem de sıvı yağın parlaklık verdiğini düşünüyorum.",
        "4. Yağlar eriyince suyu süzülen pirinçler eklenerek kavrulur.",
        "5. 2-3 dakika kavrulduktan sonra dolmalık fıstıklar ve kuş üzümleri ilave edilir. Beraber bir iki defa karıştırılarak kavrulur.",
        "6. Üzerine 2 su bardağı sıcak su ilave edilir. Tuzu ayarlanır. Tencerenin kapağı kapatılarak pişmeye bırakılır.",
        "7. Pilav suyunu çekinceye kadar pişirilir. Bu ölçüdeki pirinç için suyu bilerek az kullanıyoruz, pilavımız biraz diri kalacak.",
        "8. Son olarak ocaktan alınır ve tarçın ve karabiber eklenerek nazikçe karıştırılır.",
        "9. Diğer taraftan bütün tavuğumuz yıkanır ve varsa tüyleri ütülenir. Bu tarifte organik tavuk kullandım. Eğer bulabilirseniz köy tavuğu daha geç pişer ama daha sağlıklı ve lezzetli olacaktır, tavsiye ederim.",
        "10. Tavuğun içi fazla bastırmadan pilavla doldurulur. Çok sıkıştırırsanız pilavınız hamur olabilir.",
        "11. Tavuğun ayakları ya derisinden geçirilerek sıkıştırılır veya mutfak ipi ile bağlanır, böylece pişerken açılması önlenmiş olur.",
        "12. Bir kasede sos malzemeleri karıştırılır ve fırça ile tavuğun her yerine gelecek şekilde sürülür.",
        "13. Fırın torbasına un alınır. Poşet çevrilip sallanarak unun her yerine gelmesi sağlanır.",
        "14. Ardından sosladığımız tavuğu poşetin içerisine dikkatli bir şekilde yerleştirelim. Garnitür olarak tavuğun yanına arpacık soğan, patates, havuç, ince kesilmiş limon dilimleri ve birkaç yaprak defne kullandım.",
        "15. Poşetin ağzını kapattıktan sonra bir kürdanla poşetin üzerine delikler açalım.",
        "16. Tavuğumuzu önceden 190 dereceye ısıttığımız fırında 60 dakika boyunca pişmeye bırakalım.",
        "17. Tencerede kalan pilava sıcak su ilave ederek pişirmeye devam edelim.  Tekrar suyunu çektiğinde üzerine bir havlu kağıt kapatarak  demlenmeye bırakılır.",
        "18. 60 dakikanın sonunda tavuğu fırından alalım. Üzerindeki poşeti açarak fanlı ayarda 10 dakika daha pişirelim. Sürenin sonunda nar gibi kızaran nefis tavuk dolmamız servise hazır.",
        "19. İç pilavlı tavuk dolması nasıl servis edilir? Ben genişçe bir servis tabağının tabanına demini alan pilavı yayarak tavuk için bir yatak oluşturdum ve fırından çıkan tavuğu pilavın ortasına yerleştirdim. Pişen sebzelerimi de gelişigüzel pilavın üzerine serpiştirdim, tercih sizin, şimdiden afiyet olsun."
    ],
    chefTip: "İç Pilavlı Tavuk Dolması Nasıl Yapılır? hazırlarken malzemelerin taze olması ve pişerken kısık ateşte demlenmesi lezzeti iki katına çıkarır! 💡",
  ),
  Recipe(
