    title: "Lezzet Bombası İrmikli Şerbetli Tatlı (Videolu)",
    emoji: "🧁",
    imageUrl: "https://i.nefisyemektarifleri.com/2025/02/28/lezzet-bombasi-irmikli-serbetli-tatli-videolu.jpg",
    prepTimeMinutes: 55,
