    calories: 954,
    mealType: MealTypeFilter.dessert,
    ingredientsText: ["• 150 gram oda sıcaklığında yumuşamış tereyağı", "• 1 çay bardağı pudra şekeri", "• 1 adet yumurta", "• 3 yemek kaşığı irmik", "• 1 paket vanilya", "• 1 tatlı kaşığı kabartma tozu", "• 2,5 – 3 su bardağı un", "• Şerbeti için:", "• 2 su bardağı toz şeker", "• 2 su bardağı su", "• Bir kaç damla limon suyu"],
