        "2. Kaynamaya başlayınca ocağın altını kısıp 15 dk kaynatıyoruz.",
        "3. Ardından bir kaç damla limon suyu ekleyip 5 dakika daha ocakta bekletiyoruz ( şerbetin toplam kaynama süresi en kısık ateşte 20 dk)",
        "4. Ocaktan alıp soğumaya bırakıyoruz.",
        "5. Hamuru için;oda sıcaklığında yumuşamış tereyağı ve diğer malzemeleri ekleyerek ele yapışmayan yumuşak bir hamur elde ediyoruz (un yavaş yavaş kontrollü eklenmeli ! )",
        "6. Hamurdan ceviz büyüklüğünde parçalar koparıp elde yuvarlayarak şekil veriyoruz keskin bir bıçakla üzerine çizikler atıp fırın tepsisine aralıklı olarak diziyoruz.",
        "7. 180 derece önceden ısıtılmış fırında kızarana kadar kontrollü pişiriyoruz .",
        "8. Fırından aldıktan hemen sonra tamamen soğumuş olan şerbeti üzerine gezdirerek üzerini tepsiyle kapatıp 4-5 saat şerbetini tamamen çekmesi için bekletiyoruz.",
        "9. Bir gece önceden yaparsanız şerbetini tam çekmiş olur 👍 sizleri burcunun mutfağı youtube ve burcunun__mutfagii instagram sayfalarıma da beklerim 🌸."
    ],
    chefTip: "Lezzet Bombası İrmikli Şerbetli Tatlı (Videolu) hazırlarken malzemelerin taze olması ve pişerken kısık ateşte demlenmesi lezzeti iki katına çıkarır! 💡",
  ),
  Recipe(
    id: "r_15",
    title: "Airfryer Sufle Tarifi",
    emoji: "🧁",
    imageUrl: "https://i.nefisyemektarifleri.com/2022/12/12/airfryer-sufle-tarifi.jpg",
    prepTimeMinutes: 15,
    difficultyStars: 1,
    calories: 587,
    mealType: MealTypeFilter.dessert,
    ingredientsText: ["• 2 paket bitter çikolata", "• 3 yumurta", "• Yarım su bardağı un", "• Yarım su bardağı şeker", "• 1 çimdik tuz", "• 50 gram tereyağı"],
    requiredIngredients: [getIng('cikolata'), getIng('seker'), getIng('tereyagi'), getIng('tuz'), getIng('un'), getIng('yumurta')],
    steps: [
        "1. Çikolatalı sufle için öncelikle tereyağını eritip içine çikolata parçalarını ekleyip çikolatalar eriyinceye kadar karıştıralım. Bu işlemi bir kaç şekilde yapabilirsiniz. Örneğin tavada yağı eritip ocağı en kısığa alıp veya kapatıp çikolataları da eritebilirsiniz. Veya mikrodalga fırında eritebilirsiniz. Veya da airfryer de 100 derecede 2-3 dakikada eritmeniz mümkün.",
        "2. Çırpma kabında yumurtalar ve şekeri bir çimdik tuzla iyice köpük köpük oluncaya kadar çırpalım.",
        "3. İçerisine eriyen tereyağlı çikolata (çok sıcak olmasın, gerekirse ılımasını bekleyin) ve unu ekleyip tekrar çırpalım.",
        "4. Sufle kaplarının içini çok az tereyağı ile yağlayalım.",
        "5. Hamuru kaplara boşaltalım. Benim kaplarım büyük biraz, bu ölçü ile 3 kap dolusu çıkıyor fazla fazla, eğer orta boy kap ile yaparsanız 4 kişi için rahatlıkla yeterli gelecektir.",
        "6. Sufle kaplarını airfryer ızgarası üzerine yerleştirelim. Benim kullandığım model philips xxl airfryer, pişme süresini ve sıcaklığı kendi airfryerıma göre veriyorum, artık çok farklı modeller var, siz kendinize göre gerekirse değiştirebilirsiniz. 190 derecede 5 dakika pişmeye bırakalım. İlk 4. Dk da gerekirse bir açıp hızlıca bakabilirsiniz, üzeri kabuklanmış ve pişmişse hazır demektir. Zaten içinin akışkan kalmasını istiyoruz. Pişme süresi kapların büyüklüğüne veya airfryer modeline göre farklılık gösterebilir.",
        "7. Sufleleri sıcağıyla servis edelim. Ben üzerine az pudra şekeri serpip birer parça çikolata batırdım. Dilerseniz bir top dondurma ile de servis edilebilir. Şimdiden herkese afiyet olsun :)"
    ],
    chefTip: "Airfryer Sufle Tarifi hazırlarken malzemelerin taze olması ve pişerken kısık ateşte demlenmesi lezzeti iki katına çıkarır! 💡",
  ),
  Recipe(
