    ingredientsText: ["• Güllaç için;", "• 8 adet güllaç yaprağı", "• 1 litre süt", "• 1 su bardağı toz şeker", "• Kreması için;", "• 1 çay bardağı mısır nişastası", "• Yarım su bardağı un", "• 1 paket vanilin şekeri", "• 80 gram beyaz çikolata", "• Yarım paket sıvı krema", "• Arası için;", "• Antep fıstığı", "• Üzeri için;", "• Hindistan cevizi"],
    requiredIngredients: [getIng('ceviz'), getIng('cikolata'), getIng('krema'), getIng('misir'), getIng('nisasta'), getIng('seker'), getIng('sut'), getIng('un')],
    steps: [
        "1. Tencereye süt, un, nişasta ve şekeri alarak, ocağın altını açmadan çırpma teli ile güzelce çırpalım.",
        "2. Ocağın altını açalım ve sürekli karıştırarak kıvam alana kadar pişirelim.",
        "3. Kaynamaya başladıktan sonra vanilya ve beyaz çikolatayı ekleyerek çikolata eriyene kadar karıştıralım.",
        "4. Ocağı kapatalım ve soğuması için ayrı bir kaba aktararak bir kenarda bekletelim.",
        "5. Soğuduktan sonra üzerine sıvı kremayı ekleyelim ve mikserle güzelce çırpalım.",
        "6. Şerbeti için tencereye süt ve şekeri alıp karıştırarak sadece ısıtalım. Ilık olması gerekiyor, kaynatmamaya dikkat edelim.",
        "7. Güllaç yapraklarını kullanacağımız kabın şekline göre keselim. Ben 28×28 kare borcam kullandım.",
        "8. 4 kat güllaç yaprağını aralarını hazırladığımız şerbetle hiç kuru yeri kalmayacak şekilde ıslatarak üst üste yerleştirelim.",
        "9. Son güllaç yaprağının da her yerini ıslattıktan sonra üzerine hazırladığımız kremayı güzelce yayalım. Dilerseniz bu aşamada kremanın yarısını kullanıp, kalan yarısını tatlının en üst katına dökerek de hazırlayabilirsiniz.",
        "10. Bolca Antep fıstığı da serpttikten sonra kalan güllaç yapraklarını aynı şekilde şerbetle güzelce ıslatarak yerleştirelim.",
        "11. Tatlımızı buzdolabında en az 3-4 saat dinlendirelim.",
        "12. Dinlenen tatlının üzerine bolca Hindistan cevizi serpelim ve dilediğimiz şekilde süsleyelim.",
        "13. Afiyet olsun!."
    ],
    chefTip: "Kardelen Güllaç hazırlarken malzemelerin taze olması ve pişerken kısık ateşte demlenmesi lezzeti iki katına çıkarır! 💡",
  ),
