  Recipe(
    id: "r_19",
    title: "Taş Kadayıf Tatlısı Yapılışı",
    emoji: "🧁",
    imageUrl: "https://i.nefisyemektarifleri.com/2021/07/19/tas-kadayif-tatlisi-yapilisi-1.jpg",
    prepTimeMinutes: 50,
    difficultyStars: 3,
    calories: 305,
    mealType: MealTypeFilter.dessert,
    ingredientsText: ["• Şerbeti için;", "• 2,5 su bardağı su", "• 2 su bardağı şeker", "• Çeyrek limon suyu", "• Hamuru için;", "• 1 su bardağı ılık süt", "• 1 su bardağı su", "• 1,5 su bardağı un", "• 1 tatlı kaşığı kuru maya", "• 1 tatlı kaşığı şeker", "• 1 çay kaşığının ucu ile tuz", "• İçi için;", "• İnce çekilmemiş ceviz", "• Tarçın", "• Kızartmak için;", "• Sıvı yağ"],
    requiredIngredients: [getIng('ceviz'), getIng('limon'), getIng('seker'), getIng('siviyag'), getIng('sut'), getIng('tuz'), getIng('un')],
    steps: [
        "1. Tencereye şeker ve  suyu alalım. Şeker eriyene kadar karıştıralım ve kaynamaya bırakalım.",
        "2. Yaklaşık 10 dakika kadar kaynayan şerbete çeyrek limonun suyunu ilave edelim ve bir 5 dakika kadar daha kaynatalım.",
        "3. Ardından şerbeti soğuması için bekletelim.",
        "4. Tatlımızın hamuru için,  ılık süt, su, kuru maya, şeker,  tuz ve unu uygun bir kaseye alalım. Hiç topak kalmayıncaya kadar karıştıralım.",
        "5. Harcımızın mayalanması için üzerini streç filmle kapatalım ve bekletelim.",
        "6. Daha sonra iyice ısıttığımız teflon tavaya mayalanan hamurdan bir kepçe dökelim.",
        "7. Hamurun sadece alt kısmını pişirelim, üstü göz göz olup altı da kızarınca tavadan alabiliriz.",
        "8. Pişen hamuru temiz bir bezin üzerine alarak bekletelim.",
        "9. Hamurumuz bitene kadar aynı işlemleri tekrarlayalım. Pişirme aşaması için tavanın yeterince ısınması çok önemli, aksi takdirde hamur istenilen şekilde pişmeyecektir.",
        "10. Şimdi iç harcını hazırlayalım. Bunun için iri doğranmış cevize tarçın ilave edip güzelce karıştıralım. Tarçın miktarını dilediğiniz şekilde ayarlayabilirsiniz ya da hiç kullanmayabilirsiniz.",
        "11. Cevizli harcı, hamurların pişmeyen orta kısmına bolca yerleştirelim.",
        "12. Ardından hamurumuzu kapatalım. Kenarlara iyice bastıralım ki açılmasınlar.",
        "13. Tüm hamurlara aynı şekilde, bolca iç harç yerleştirip sıkıca kapatalım. Bu arada tarifin orijinali cevizle olsa da siz dilerseniz fındık ya da fıstık kullanarak da hazırlayabilirsiniz.",
        "14. Dondurucuda saklamak için fermuarlı poşetimizden bir tane alalım ve saklamak istediğimiz kadarını yerleştirelim. Fermuarlı poşetimizi kapatalım ve dondurucuya kaldıralım. Bu şekilde tatlıyı servis etmek istediğiniz ana kadar muhafaza edebilirsiniz.",
        "15. Kızgın yağa aldığımız kadayıfları önlü arkalı güzelce kızartalım. Kadayıflarımızı dışı iyice koyulaşana kadar, arkalı önlü kızartalım. Böylece tatlımız çıtır çıtır ve çok lezzetli olacak.",
        "16. Diğer yandan soğuk şerbetimizi uygun bir borcama dökelim. Ben şerbet ılıyınca buzdolabına kaldırdım. Bu tarifte şerbetimizin soğuk, tatlımızın sıcak olması gerekiyor.",
        "17. Kızaran taş kadayıfları direkt soğuk şerbetin içerisine aktaralım. Birkaç dakika şerbetin içinde beklettikten sonra servis tabağına alabilirsiniz.",
        "18. Tüm kadayıfları kızartıp şerbetledikten sonra dilediğiniz gibi süsleyerek servis edebilirsiniz. Ben hem renk vermesi hem de lezzeti arttırması için toz fıstık ile süsledim."
    ],
    chefTip: "Taş Kadayıf Tatlısı Yapılışı hazırlarken malzemelerin taze olması ve pişerken kısık ateşte demlenmesi lezzeti iki katına çıkarır! 💡",
  ),
  Recipe(
    id: "r_20",
    title: "Cevizli Baklava Tarifi (videolu)",
    emoji: "🥗",
    imageUrl: "https://i.nefisyemektarifleri.com/2020/05/22/ev-baklavasi-12.jpg",
    prepTimeMinutes: 35,
    difficultyStars: 2,
    calories: 421,
    mealType: MealTypeFilter.mainCourse,
    ingredientsText: ["• Şerbeti için;", "• 4 su bardağı şeker", "• 4 su bardağı su", "• 1 tatlı kaşığı limon suyu", "• Hamuru için;", "• 3,5 su bardağı un", "• 2 adet yumurta", "• 1 çay bardağı sıvı yağ", "• 1 çay bardağı süt", "• 1 yemek kaşığı sirke", "• Çay kaşığı ucu ile Tuz", "• Hamuru açmak için;", "• Nişasta", "• Arası için;", "• 2 su bardağı ceviz kırığı", "• Üzerine;", "• 250g tereyağı", "• Yarım çay bardağı sıvı yağ"],
    requiredIngredients: [getIng('ceviz'), getIng('limon'), getIng('nisasta'), getIng('seker'), getIng('siviyag'), getIng('sut'), getIng('tereyagi'), getIng('tuz'), getIng('un'), getIng('yumurta')],
    steps: [
        "1. İlk olarak tatlımızın şerbetini hazırlayalım. Bunun için uygun bir tencereye şeker ve suyu alalım.",
        "2. Karıştırdıktan sonra şerbetimizi kaynamaya bırakalım.",
        "3. Sürenin sonunda limon suyunu da ilave ederek bir kaç dakika daha kaynatalım ve ocaktan alalım.",
        "4. Baklava hamuru için yoğurma kabına yumurta, sıvı yağ, süt, sirke ve tuzu alarak karıştıralım.",
        "5. Daha sonra unu yavaş yavaş  ilave ederek hamurumuzu ele yapışmayan bir kıvam alıncaya  kadar yoğuralım.",
        "6. Yoğurduğumuz hamurumuzun üzerini streçleyerek 30 dakika kadar dinlenmeye bırakalım. Bu şekilde hamurumuz çok daha kolay açılacaktır.",
        "7. Süre sonunda hamurumuzu tezgaha alalım ve bir iki kere daha yoğurarak toparlayalım.",
        "8. Hamurumuzu ilk önce eşit bir şekilde 3 parçaya ayıralım, daha sonra her parçayı da 9 parçaya ayıralım.",
        "9. Böldüğümüz parçaları dıştan içe doğru yoğurup, elimizde yuvarlayarak beze haline getirelim. Toplamda 27 adet beze elde etmiş olacağız.",
        "10. Tüm parçaları beze haline getirdikten sonra üzerlerini streç filmle kapatalım. Böylece hamur açma işlemi bitene kadar kurumalarını engellemiş olacağız.",
        "11. Bezelerimizinden bir tanesini nişasta serptiğimiz tezgaha alalım, merdane yardımı ile tatlı tabağı boyutunda açalım. Bu şekilde ilk 9 bezeyi tek tek açalım, aralarına nişasta serperek üst üste yerleştirelim.",
        "12. Daha sonra hazırladığımız 9 kat hamuru tepsi boyutundan biraz büyük olacak şekilde arada bir ters-yüz ederek açalım. Burada hamuru ters yüz ettiğinizde altta kalan küçük katlarda eşit oranda genişleyecektir.",
        "13. Daha sonra hamuru yine dikkatli bir şekilde, nazikçe katlarına ayıralım.",
        "14. Elde ettiğimiz incecik, zar gibi baklava hamurunu tepsimize yerleştirelim. Dilerseniz benim gibi yufkaları ayırarak koyabileceğiniz gibi ayırmadan bütün bir şekilde de koyabilirsiniz.",
        "15. İlk 9 katı tepsiye yerleştirdikten sonra üzerine ceviz kırıkları serpiştirelim. Dilerseniz bu aşamada fındık veya fıstıkta koyabilirsiniz.",
        "16. Diğer 9 bezeyı de aynı şekilde açarak, aralarına nişasta serpelim ve üst üste yerleştirelim. Ardından tepsi boyutunda genişletelim.",
        "17. Genişlettiğimiz hamuru tekrar katlarına ayırarak tepsimize yerleştirelim.Eğer siz de katları tek tek yerleştirecekseniz ve yeriniz de müsaitse, hamurları kurumaları için bir yere serip, 3-4 dakika bekletebilirsiniz.",
        "18. Tepsiye yerleştirdiğimiz hamurların üzerine ceviz kırığı serpelim.",
        "19. Son 9 bezemizi de aynı işlemleri uygulayarak tepsi boyutunda genişletelim ve tepsimize yerleştirelim.",
        "20. Baklavamızı keserken ilk önce 4 parçaya keselim. Daha sonra bu 4 parçayı da küçük üçgenlere ayıralım.",
        "21. Son olarak eritilmiş tereyağı ve sıvı yağ karışımını baklavamızın üzerine gezdirelim ve önceden ısıttığımız 170°C fırında 1 saat kadar pişmeye bırakalım.",
        "22. Süre sonunda fırından aldığımız sıcak baklavaların üzerine soğuyan şerbetimizi gezdirelim ve şerbetini çekmesi için dinlenmeye bırakalım. Deneyeceklere şimdiden afiyet olsun."
    ],
    chefTip: "Cevizli Baklava Tarifi (videolu) hazırlarken malzemelerin taze olması ve pişerken kısık ateşte demlenmesi lezzeti iki katına çıkarır! 💡",
  ),
