  Recipe(
    id: "r_29",
    title: "Lübnan Köftesi (Falafel)",
    emoji: "🥗",
    imageUrl: "https://i.nefisyemektarifleri.com/2021/07/26/lubnan-koftesi-falafel-7.jpg",
    prepTimeMinutes: 25,
    difficultyStars: 2,
    calories: 174,
    mealType: MealTypeFilter.mainCourse,
    ingredientsText: ["• 2 su bardağı nohut", "• 1 adet soğan", "• 2 diş sarımsak", "• 1 adet yumurta", "• 1 su bardağı un", "• 1 çay kaşığı karbonat", "• Yarım demet maydanoz", "• 1 tatlı kaşığı toz kişniş", "• 1 tatlı kaşığı karabiber", "• 1 çay kaşığı tuz", "• Sosu için;", "• 4 yemek kaşığı süzme yoğurt", "• 2 yemek kaşığı tahin", "• 1 yemek kaşığı limon suyu", "• Yarım çay kaşığı tuz", "• Kızartmak için;", "• Sıvı yağ"],
    requiredIngredients: [getIng('biber'), getIng('karabiber'), getIng('limon'), getIng('maydanoz'), getIng('nohut'), getIng('sarimsak'), getIng('siviyag'), getIng('sogan'), getIng('tahin'), getIng('tuz'), getIng('un'), getIng('yogurt'), getIng('yumurta')],
    steps: [
        "1. Rondoya aldığımız 1 gece öncesinden suda bekletilmiş nohuta, soğan, sarımsak ve maydanozu ekleyelim. Tüm malzemeler birleşinceye kadar rondodan geçirelim. Bu tarifte ben nohutları 1 gece öncesinden suda beklettim ancak vaktiniz yoksa haşlayarak yapmayı da deneyebilirsiniz.",
        "2. Nohutlu karışımı uygun bir kaseye aktaralım ve un,  yumurta, karabiber, toz kişniş, karbonat ve tuzu ilave edip bir kaşık yardımıyla güzelce karıştıralım.",
        "3. Ardından harcın üzerini streç filme kapatıp, 1 saat kadar buzdolabında dinlendirelim.",
        "4. Sürenin sonunda harçtan ceviz büyüklüğünde parçalar kopartıp yuvarlayalım.",
        "5. Köfte şekli verilen hamuru streç film serili bir tepsiye dizelim. Tüm hamur bitene kadar aynı şekilde parçalar kopartıp yuvarlayalım.",
        "6. Kızartmak için tavaya sıvı yağ alarak kızdıralım. Ardından falafellerimizin her iki tarafını da güzelce kızartalım.",
        "7. Eğer falafellerinizi direkt pişirmeden buzlukta saklamak isterseniz, donmaları için birkaç saat buzlukta bekletebilir, ardından fermuarlı poşetten bir tane alıp, donan falafelleri içerisine yerleştirebilirsiniz. Bu yöntemi dilerseniz artan falafelleri saklamak için, dilerseniz de ihtiyacınız olduğu an çıkarıp pişirmek için kullanabilirsiniz. Kızartacağınız zaman yine çözünmelerini beklemeden direkt kızgın yağda kızartabilirsiniz.",
        "8. Falafelin sosu için; süzme yoğurda, tahin, limon suyu ve tuzu ekleyelim. Tüm malzemeler homojen bir kıvama gelinceye kadar güzelce karıştıralım.",
        "9. Kıazaran falafellerimizi tahinli sosu ile birlikte servis edebiliriz. Deneyeceklere şimdiden afiyet olsun!"
    ],
