        "5. Hamuru için derin bir kap içerisine bulgur ve irmiğimizi alalım, üzerine sıcak suyu ekleyerek kabımızı streç ile kapatalım. 10 dakika kadar bulgurların şişmesi için bekletelim.",
        "6. Sürenin sonunda streci çıkartalım ve un, yumurta, biber salçası ve baharatları ekleyerek tüm malzemeler güzelce karışana kadar elimizle yoğuralım.",
        "7. Tezgah üzerine streç filmimizden bir parça alalım, üzerine hamurumuzun bir kısmını alalım.",
        "8. Üzerine tekrar streç film kapatalım ve elimizle hafifçe düzleştirelim. Ardından merdane yardımı ile hamurumuzu açalım.",
        "9. Hamurumuzu istediğimiz inceliğe getirdikten sonra üstteki streci alalım ve kesme aparatı ile daireler şeklinde keselim.",
        "10. Kenarlarda kalan hamurları ayıralım ve dairelerimizin ortasına kıymalı harcımızdan bolca yerleştirelim.",
        "11. Dairelerimizi kapatabilmek için streç filmimizi 3 parçaya keselim, içli köftelerimizi ortadan ikiye olacak şekilde katlayalım.",
        "12. Elimizi su ile ıslatalım ve içli köftelerimizin birleşim yerlerini düzeltelim. Hamurumuzun bitene kadar bu işlemlere devam edelim. Ben bu ölçülerle hazırladığımda toplamda 31 adet içli köfte elde ettim.",
        "13. İçli köftelerimizi kızartmak için derin bir tencere içerisine sıvı yağ alalım ve kızdıralım.",
        "14. Ardından içerisine içli köftelerimizi alalım ve çevirerek kızartalım. Güzelce kızaran köftelerimizi havlu kağıt serili bir tabak içerisine alalım ve servis edelim.",
        "15. Ben tüketeceğim kadar içli köfteyi kızarttım, kalanlarını buzlukta muhafaza ettim. Bunun için tepsiye dizdiğim içli köftelerin üzerini streç ile kapattım ve buzluğa kaldırarak bir kaç saat beklettim. Ardından buzluktan aldım ve kilitli poşet içerisine koyarak tekrar buzluğa attım. Deneyeceklere şimdiden afiyet olsun."
    ],
    chefTip: "Kızartma İçli Köfte (videolu) hazırlarken malzemelerin taze olması ve pişerken kısık ateşte demlenmesi lezzeti iki katına çıkarır! 💡",
