    requiredIngredients: [getIng('bezelye'), getIng('biber'), getIng('havuc'), getIng('karabiber'), getIng('patates'), getIng('salca'), getIng('sarimsak'), getIng('sogan'), getIng('tavuk'), getIng('tuz'), getIng('zeytinyagi')],
