        "7. Son olarak doğradığımız kırmızı biberleri ve bezelyeyi de ekleyerek pişirmeye devam edelim.",
        "8. Üzerine doğradığımız sarımsağı ve salçayı da ilave ederek güzelce karıştıralım ve sıcak suyu ekleyelim.",
        "9. Tuzunu da ayarlayıp karıştıralım ve ocaktan alalım.",
        "10. Tezgaha pişirme kağıdını alarak serelim, ortasına bir porsiyon kadar sebzeli tavuğumuzdan yerleştirelim.",
