        "13. Tepsiye yerleştirirken kağıt kebaplarımızın katladığımız üst düzeyinin çevirerek alta gelmesini sağlayalım.   Biz bu ölçülerle dolu dolu 5 porsiyon kağıt kebabı hazırladık.",
        "14. Kağıt kebaplarımızı önceden ısıtılmış 180° fırında yaklaşık 20-25 dk pişmeye bırakalım.",
        "15. Fırından çıkan kağıt kebaplarımızı sıcağı ile servis edelim. Afiyet olsun :)"
