  Recipe(
    id: "r_42",
    title: "Susamlı Tatlı Kurabiye (videolu)",
    emoji: "🧁",
    imageUrl: "https://i.nefisyemektarifleri.com/2021/02/17/susamli-tatli-kurabiye-8.jpg",
    prepTimeMinutes: 35,
    difficultyStars: 2,
    calories: 84,
    mealType: MealTypeFilter.dessert,
    ingredientsText: ["• 1 su bardağı susam", "• 2 adet yumurta (birinin akı üzerine)", "• 125 g tereyağı", "• 1 çay bardağından biraz az sıvı yağ", "• 1 çay bardağı pudra şekeri", "• 1 paket vanilya", "• 1 paket kabartma tozu", "• 3,5 su bardağı un"],
    requiredIngredients: [getIng('seker'), getIng('siviyag'), getIng('tereyagi'), getIng('un'), getIng('vanilya'), getIng('yumurta')],
    steps: [
        "1. İlk olarak susamlarımızı kavuralım. Bunun için tavamıza bir su bardağı susamı alalım, susamlar renk değiştirip altın sarısı rengini alıncaya kadar kavuralım.",
        "2. Kavrulan susamları ocaktan alalım, uygun bir tabak içerisine dökerek soğumaya bırakalım.",
        "3. Kurabiye hamurumuz için yoğurma kabına birinin akı üzeri için ayırdığımız  yumurta, oda sıcaklığındaki  tereyağı, sıvı yağ, pudra şekeri ve vanilyayı alalım. Malzemeleri elimizle güzelce homojen bir kıvam alıncaya kadar karıştıralım. Tereyağı ve yumurtalarınızın oda sıcaklığın da olmasına dikkat edin.",
        "4. Daha sonra biraz un ve kabartma tozunu ilave ederek hamurumuzu yoğurmaya başlayalım. Unun cinsine kalitesine ve malzemelerdeki ufak tefek farklılıklardan dolayı un miktarı çok az değişebilir, o yüzden bakarak yavaş yavaş eklemeye dikkat edelim. Hem bu şekilde yoğurması da çok daha kolay olacaktır.",
        "5. Kurabiye hamurumuz hazır. Şimdi fırın tepsimize pişirme kağıdından bir tane çıkarıp yerleştirelim.",
        "6. Daha sonra hamurumuzu şekillendirme aşamasına geçebiliriz. Bunun için hamurdan ceviz büyüklüğünde parçalar alarak avuç içerisinde yuvarlayıp şekil verelim. Bu hamurla benim hazırladığım boyutta toplamda 30 adet kurabiye elde ediyoruz.",
        "7. Şekillendirdiğimiz kurabiyelerimizin her tarafına önce yumurta akına ardından kavurduğumuz susama bulayalım. Ben kurabiyelerimi şekillendirdikten sonra bu işlemi yapıyorum.",
        "8. Kurabiyelerimizi önceden ısıttığımız 170° fırında yaklaşık 35 dakika pişmeye bırakalım. Pişen kurabiyelerimiz servise hazır. Afiyet olsun."
    ],
    chefTip: "Susamlı Tatlı Kurabiye (videolu) hazırlarken malzemelerin taze olması ve pişerken kısık ateşte demlenmesi lezzeti iki katına çıkarır! 💡",
  ),
  Recipe(
