    ingredientsText: ["• 600 g tavuk göğsü", "• Tuz", "• 2 adet kırmızı biber", "• 3 adet yufka", "• Patates kızartması", "• Kaşar rendesi", "• Marine için;", "• 1 yemek kaşığı domates salçası", "• Yarım çay bardağı zeytinyağı", "• 1 çay kaşığı kekik", "• 1 çay kaşığı pulbiber", "• Yarım çay kaşığı karabiber", "• 1 çay kaşığı toz kırmızı biber", "• Üzeri için;", "• 1 adet yumurta sarısı", "• 1 tatlı kaşığı yoğurt", "• Susam", "• Çörekotu"],
    requiredIngredients: [getIng('biber'), getIng('domates'), getIng('karabiber'), getIng('kasar'), getIng('kekik'), getIng('patates'), getIng('salca'), getIng('tavuk'), getIng('tuz'), getIng('yogurt'), getIng('yufka'), getIng('yumurta'), getIng('zeytinyagi')],
    steps: [
        "1. İlk olarak tavuk göğsümüzü ince uzun, julyen şeklinde doğrayalım.",
        "2. Daha sonra çift kilitli poşet içerisine salça, zeytinyağı, kekik, pulbiber, toz kırmızı biber ve karabiberi ekleyerek poşetin dışından karıştıralım.",
        "3. Üzerine de doğradığımız etlerimizi ekleyerek karıştıralım, marine olması için buzdolabında 2 saat kadar dinlendirelim.",
        "4. Süre sonunda tavamızı kızdıralım ve marine olan tavuklarımızı yüksek ateşte karıştırarak soteleyelim. Bu aşamada sürekli karıştırmaya ve tavuklarımızı yakmamaya dikkat edelim.",
        "5. Tavuklarımız güzelce piştikten sonra üzerine yeteri kadar tuz ve doğradığımız kırmızı biberleri ekleyerek bir kaç dakika daha karıştırarak sotelemeye devam edelim.",
        "6. Yufkamızı tezgaha alalım, uç kısmından bir tarafını içe doğru katlayalım.",
        "7. Katladığımız kısma iç harcımızın üçte birini boşaltalım, üzerine patates kızartması ve kaşar peyniri rendesi yerleştirelim.",
        "8. Yufkamızın kenarlarını içe doğru katlayalım ve yufkamızı saralım.",
        "9. Sardığımız yufkamızı ortadan keselim ve pişirme kağıdı yerleştirdiğimiz fırın tepsimize alalım. Tavuklu harcımız bitene kadar bu işleme devam edelim.",
        "10. Fırın tepsimize yerleştirdiğimiz dürümlerimizin üzerine yumurta sarısı ve yoğurt karışımından sürelim, susam ve çörek otu da serptikten sonra önceden ısıtılmış 200°C fırında yaklaşık 15 dakika, üzerleri güzelce kızarana kadar pişirelim. Pişen ve nar gibi kızaran Tavuk Dürümlerimiz servise hazır. Afiyet olsun."
