        "10. Ben ilk yüzeyini yaklaşık 15 dakika kadar pişirdim. Daha sonra düz bir kapak yardımı ile tersini çevirdim ve diğer yüzeyini de 10 dakika pişirdim. Bu şekilde içi tamamen pişmiş oldu. Siz ocak ısınıza göre süreyi ayarlayabilirsiniz. Fikir vermesi açısından belirtiyorum lütfen kontrollü bir şekilde pişirin.",
        "11. Her iki yüzeyini de kızarttığımız böreğimizi servis tabağına alalım. İlk sıcağı çıktıktan sonra servis edebilirsiniz. Deneyeceklere afiyet olsun."
