  Recipe(
    id: "r_50",
    title: "Şekerpare Tarifi (Kıyır Kıyır)",
    emoji: "🧁",
    imageUrl: "https://i.nefisyemektarifleri.com/2021/10/06/sekerpare-tarifi-kiyir-kiyir.jpg",
    prepTimeMinutes: 40,
    difficultyStars: 2,
    calories: 214,
    mealType: MealTypeFilter.dessert,
    ingredientsText: ["• 125 gram oda ısısında margarin veya tereyağı", "• 1 adet yumurta", "• 1 çay bardağı irmik", "• 1 çay bardağı pudra şekeri", "• 1 çay bardağı sıvı yağ", "• 1 paket vanilya", "• 1 paket kabartma tozu", "• 3 su bardağı un (kontrollü eklenecek)", "• Şerbeti için ;", "• 2 su bardağı toz şeker", "• 2,5 su bardağı su", "• 1-2 damla limon suyu", "• 1 dilim limon", "• Üzeri için;", "• Fındık"],
    requiredIngredients: [getIng('findik'), getIng('irmik'), getIng('limon'), getIng('seker'), getIng('siviyag'), getIng('tereyagi'), getIng('un'), getIng('vanilya'), getIng('yumurta')],
    steps: [
        "1. Öncelikle şerbeti hazırlıyoruz ki soğusun. Uygun bir tencereye su ve şekeri alıp, ocağın altını açmadan şekeri karıştırarak eritip, ocağın altını açıyoruz kaynayana kadar arada karıştırıyoruz.",
        "2. Kaynamaya başladıktan sonra ocağı kısıyoruz ve 10 dakika bu şekilde kaynatmaya devam ediyoruz.",
        "3. Sürenin sonunda bir iki damla limon sıkıp, ince bir limon dilimi atıyoruz şerbetimizin içine.",
        "4. 2-3 dakika da bu şekilde kaynadıktan sonra altını kapatıp, soğumaya bırakıyoruz.",
        "5. Hamuru için; yoğurma kabımıza un, kabartma tozu, vanilya hariç tüm malzemeleri alıp, güzelce karıştırıyoruz.",
        "6. Ardından eleyerek unu, vanilyayı, kabartma tozunu ekleyip, yumuşak kıvamlı hamur elde ediyoruz. (un kontrollü eklenmeli).",
        "7. Cevizden biraz büyük olacak şekilde parçalar koparıp, yuvarlayıp yağlı kağıt serili fırın tepsimize koyuyoruz.",
        "8. Tüm hamurumuza bu şekilde yaptıktan sonra üzerine fındık koyup, önceden ısıtılmış 180 derecelik fırında üzerleri kızarana kadar 25-30dk pişiriyoruz. ( dilerseniz üzerine bir şey koymadan da yapabilirsiniz, şerbetledikten sonra hindistan cevizi de ekleyebilirsiniz veya ceviz, fıstık vs). Fırından fırına pişirme süresi değişebileceği için kontrollü pişirilmeli.",
        "9. Pişen şekerparelerimizi fırından alıp, şerbetin içine atıp, başka bir kaba dizip, kalan şerbeti üzerinde gezdirip, 1 gece dinlendiriyoruz.  Dilerseniz şerbetin içine hiç atmadan, ayrı bir kap içerisine aldıktan sonra şerbeti direkt üzerine gezdirebilirsiniz.",
        "10. Şerbetini çekmesi için birkaç saat ya da mümkünse 1 gece dinlendirdiğimiz kıyır şekerparelerimiz servise hazır, afiyet olsun! :)"
    ],
    chefTip: "Şekerpare Tarifi (Kıyır Kıyır) hazırlarken malzemelerin taze olması ve pişerken kısık ateşte demlenmesi lezzeti iki katına çıkarır! 💡",
  ),
  Recipe(
    id: "r_51",
    title: "Muhallebili Milföy Çanakları ( Denemeyen Kalmasın)",
    emoji: "🧁",
    imageUrl: "https://i.nefisyemektarifleri.com/2017/05/04/muhallebili-milfoy-canaklari-denemeyen-kalmasin.jpg",
    prepTimeMinutes: 35,
    difficultyStars: 2,
    calories: 15,
    mealType: MealTypeFilter.dessert,
    ingredientsText: ["• 20 adet milföy hamuru ( çiftli olursa 10 adet)", "• Yumurta sarısı", "• Muhallebisi için;", "• 3 yemek kaşığı nişasta", "• 1 su bardağından biraz eksik toz şeker", "• 3 su bardağı süt", "• 1 paket vanilya", "• Üzeri için;", "• Benmari usulü eritilmiş çikolata ve çilek"],
    requiredIngredients: [getIng('cikolata'), getIng('milfoy'), getIng('nisasta'), getIng('seker'), getIng('sut'), getIng('vanilya'), getIng('yumurta')],
    steps: [
        "1. Muhallebili milföy çanaklarıiçin ilk olarak milföylerimizi tezgaha alarak bir aparat yada bardak yardımı ile yuvarlak şekilde keselim.",
        "2. Kestiğimiz milföylerin yarısını daha küçük aparat yada bardak ile tekrar keselim.",
        "3. İçi boş kalan milföylerimizi, içi dolu olan milföylerin üzerine yerleştirelim. Kalan küçük milföylerin yarısının içini de küçük bir aparat ile kesip onları da minik olarak hazırlayalım.",
        "4. Yağlı kağıt serili tepsimize milföyleri yerleştirelim. Kenarlarına yumurta sarısı sürerek, orta kısımlarına kabarmaması için çatal ile delikler açalım.",
        "5. Önceden ısıtılmış 180 derece fırında 15 dakika kadar pişirelim.",
        "6. Milföy çanaklarımızpişerken biz muhallebimizi hazırlayalım. Muhallebi için bir tencereye nişasta, şeker ve sütü alarak koyulaşıncaya kadar karıştırarak pişirelim.",
        "7. Son olarak bir paket vanilyayı ekleyerek karıştıralım ve soğumaya bırakalım.",
        "8. Pişen milföy çanaklarının orta kısımlarına parmağımız ile bastırarak çukurlaştıralım.",
        "9. Çukurları soğuyan muhallebimizden sıkarak dolduralım. Üzerini dilediğimiz gibi süsleyerek servis edelim.",
        "10. Ben muhallebili milföy çanaklarınabenmari usulü erittiğim çikolata ve çilek ile süsledim. Lezzeti ve sunumu güzel olanmuhallebili milföy çanaklarınısizlerde mutlaka deneyin.  Afiyet olsun.",
        "11. Bu tariften 10 adet büyük, 5 adet de küçükmuhallebili milföy çanağıelde edebilirsiniz.",
        "12. Kalan milföy hamurları da ben burgu yaparak şekil verdim. Üzerine yumurta sarısı sürerek fırında kızarana kadar pişirdim.",
        "13. Soğuduktan sonra üzerine pudra şekeri serperek, çikolata yada böğürtlen sosu ile servis ettim."
    ],
    chefTip: "Muhallebili Milföy Çanakları ( Denemeyen Kalmasın) hazırlarken malzemelerin taze olması ve pişerken kısık ateşte demlenmesi lezzeti iki katına çıkarır! 💡",
  ),
