        "3. Köfte harcımız hazır, şekillendirme aşamasına geçebiliriz. Harcımızdan bir parça koparalım ve avucumuzda yuvarlayıp bastırarak şeklini verelim. Resimde de görüldüğü gibi köfteler oldukça ince ve geniş görünüyor, ama piştiklerinde ortaya doğru çekiyor ve kalınlaşıyorlar. Size de mümkün olduğunca ince bir şekilde hazırlamanız tavsiye ederim, çünkü böylelikle içi daha iyi pişecektir.",
        "4. Şekillendirdiğimiz köfteleri bir tabağa dizelim.",
        "5. Köftelerimizi bu şekilde, eğer mümkünse, birkaç saat dinlenmeye bırakalım. Köfte harcı dinlendikçe daha da lezzetlenecektir.",
        "6. Köfteleri kızartmak için ızgara çizgili döküm tavayı hiç yağ eklemeden ısıtalım.",
        "7. Yeterince ısındıktan sonra köftelerimizi tavaya dizelim. Et yüksek ısıda piştiğinde çok daha lezzetli oluyor. İçindeki suyu salmadan, yumuşacık pişiyor. Bu nedenle sizlere de döküm tava kullanmanızı tavsiye ederim; fakat evinizde yoksa granit tavada da pişirebilirsiniz.",
        "8. Köftelerimizi çevirerek her iki tarafının da güzelce pişmesini sağlayalım.",
        "9. Ardından pişen köfteleri, havlu kağıt serili bir tabağa alalım. Yanında patates kızartması veya pilav eşliğinde servis edebilirsiniz."
    ],
    chefTip: "Nefis Kuru Köfte hazırlarken malzemelerin taze olması ve pişerken kısık ateşte demlenmesi lezzeti iki katına çıkarır! 💡",
  ),
