        "4. Buğdaylarımızı  dakika kaynatıp sarı suyunu süzdükten sonra geniş bir tencerenin içerisine alalım. Buğdayları 2 defa kaynatıp süzerek tekrar su ile kaynatıyorum. Bu şekilde çıkan sarı suyun aşurenin rengini bozmasını da engelliyorum.",
        "5. Üzerine 1 litre sıcak suyumuzu ekleyelim ve yaklaşık 50 dakika kadar kaynatalım. Bu aşamada gerektikçe su eklemeyi unutmayalım.",
