    mealType: MealTypeFilter.breakfast,
    ingredientsText: ["• 1 adet yumurta (sarısı üzeri için)", "• 1 su bardağı yoğurt", "• 1 çay bardağı süt", "• 1 çay bardağı sıvı yağ", "• 4 su bardağı un", "• 1 tatlı kaşığı tuz", "• 1 paket kabartma tozu", "• İç Harcı İçin;", "• Peynirli Maydanoz", "• Üzeri için;", "• Susam"],
    requiredIngredients: [getIng('beyaz_peynir'), getIng('maydanoz'), getIng('siviyag'), getIng('sut'), getIng('tuz'), getIng('un'), getIng('yogurt'), getIng('yumurta')],
    steps: [
        "1. Uygun bir yoğurma kabına yumurta akı, yoğurt, süt ve sıvı yağı alalım, malzemeleri çırpma teli ile karıştıralım.",
        "2. Ardından biraz un, tuz ve kabartma tozunu ekleyelim, hamurumuzu yoğurmaya başlayalım. Unu kontrollü bir şekilde yavaş yavaş eklemelisiniz, bu şekilde hem hamuru yoğurması kolay olacak hem de hamurun kıvamını daha iyi ayarlayabileceksiniz.",
