        "7. Şekillendirdiğimiz poğaçalarımızı pişirme kağıdı serdiğimiz fırın tepsisine yerleştirelim, üzerine her yerine gelecek şekilde ayırdığımız yumurta sarısından sürelim.",
        "8. Daha güzel görünmesi için üzerine bıçak ile çizikler atalım ve susam serperek 170°C fırında kontrollü bir şekilde yaklaşık 25 dakika pişmeye bırakalım.",
