  Recipe(
    id: "r_70",
    title: "Kakaolu Meyveli Kolay Pasta",
    emoji: "🧁",
    imageUrl: "https://i.nefisyemektarifleri.com/2026/03/06/kakaolu-meyveli-kolay-pasta.jpg",
    prepTimeMinutes: 65,
    difficultyStars: 3,
    calories: 63,
    mealType: MealTypeFilter.dessert,
    ingredientsText: ["• Kek için;", "• 3 adet yumurta", "• 1 su bardağından bir parmak eksik toz şeker", "• 1/2 (yarım) çay bardağı kaynar su", "• 1 tepeleme yemek kaşığı kakao", "• 1 su bardağı +2 yemek kaşığı un", "• 1 paket vanilya", "• 1 paket kabartma tozu", "• Pandispanyayı ıslamak için;", "• 1 su bardağı süt", "• Pasta arası için;", "• Dilediğimiz meyvelerden muz ,çilek gibi", "• Kreması için;", "• 2 su bardağı süt", "• 2 yemek kaşığı un", "• 1 yemek kaşığı nişasta", "• 4 yemek kaşığı şeker", "• 1 adet yumurta", "• 1 tatlı kaşığı tereyağı", "• Dışı için;", "• 1 poşet toz şanti", "• 1 su bardağı soğuk süt", "• Süslemek için;", "• Rendelenmiş çikolata", "• Yeşil file fıstık", "• Frenk üzümü", "• Çilek v.s."],
    requiredIngredients: [getIng('cikolata'), getIng('fistik'), getIng('kakao'), getIng('krema'), getIng('nisasta'), getIng('seker'), getIng('sut'), getIng('tereyagi'), getIng('un'), getIng('vanilya'), getIng('yumurta')],
    steps: [
        "1. Krema için,tereyağı ve vanilya hariç tüm malzemeleri tencereye alalım sürekli karıştırarak kıvam alana kadar pişirelim.",
        "2. Ocaktan alalım tereyağı ve vanilyayı ekleyelim iyice karıştıralım, bir kenarda soğumaya bırakalım.",
        "3. Fakat soğurken 3-5 dk ara ile üzeri kabuk tutmaması için karıştıralım.",
        "4. Ayrı bir çırpma kabında poşet şanti ve soğuk sütü kıvam alana kadar mikser yardımıyla iyice çırpalım, buzdolabına kaldıralım.",
        "5. Pandispanya için yumurtaları ve toz şekeri derin bir kaba alalım köpük köpük oluncaya kadar çırpalım.",
        "6. Ardından yarım çay bardağı kaynar suyu azar azar ekleyerek çırpmaya devam edelim daha sonra kakao, un, vanilya ve kabartma tozunu ekleyelim spatula yardımıyla iyice karıştıralım akışkan kıvamlı pandispanya hamurunu yağlı kâğıt serilmiş tepsiye dökelim.",
        "7. Fırın tepsimiz standart boy ise hamuru tepsinin tamamına yaymayalım ki pandispanya ince olmasın fotoğraftaki gibi 🙂",
        "8. 180 ° ısınmış fırında 20 dk pişirelim pandispanyayı fırından alalım ılıdıktan sonra üzerine fırın kâğıdı serip ters çevirelim dikkatlice pandispanyayı diğer kâğıttan ayıralım kenarlarındaki eğrilikleri keserek çıkaralım, üç eşit uzun parça elde edelim.",
        "9. Pastanın ilk katı için parçanın birini tabana alalım üzerine soğuk süt serperek ıslayalım.",
        "10. Diğer taraftaki soğuyan pasta kremasından bir katman sürelim ,ilk katına çilek sıralayalım, ikinci katı da aynı şekilde sütle ıslayıp krema yayalım, ikinci kata muz dilimleri sıralayalım, en son katı kapattıktan sonra kalan sütle ıslayalım.",
        "11. Aralardan taşan kremaları spatula ile düzeltelim buzdolabında bekleyen krem şanti ile pastanın yüzeyini kaplayalım hamur kesici yardımıyla dört kenarını ve üzerini düzeltelim.",
        "12. Diğer tarafta biter çikolata rendeleyelim ve pastanın her yerini çikolata rendesi ile kapatalım( bknz fotoğraf ) daha sonra dilediğimiz gibi süsleyelim buzdolabında 3-4 saat dinlendirelim kolay ve lezzetli pastamız hazır afiyet olsun 😋 😋😋😋."
    ],
