    requiredIngredients: [getIng('biber'), getIng('domates'), getIng('karabiber'), getIng('kekik'), getIng('kiyma'), getIng('sarimsak'), getIng('seker'), getIng('siviyag'), getIng('sogan'), getIng('sut'), getIng('tereyagi'), getIng('tuz'), getIng('un'), getIng('yogurt'), getIng('yumurta')],
    steps: [
        "1. İlk olarak pidenin hamurunu hazırlayınız. Yoğurma kabınızın içine ılık su, ılık sütü, şekeri ve mayayı ekleyip aktifleştiniz sonra diğer malzemeleri ekleyip ele yapışmayan çok yumuşak bir hamur yoğurunuz .",
        "2. Üzerine kapatıp mayalanması için kenara alını.",
        "3. Sonra mayalanan hamuru 2 eşit parçaya bölünüz ramazan pidesi büyüklüğünde açıp fırın tepsisine koyup 20 dakika tepsi mayası yapınız sonra parmaklarınızla bastırarak şekil veriniz üzerine 1 yumurta sarısı ve yoğurdu karıştırıp her tarafına gelecek şekilde sürümüz .",
        "4. Üzerine susam ve çörek otu serpiniz.",
        "5. Önceden ısıtılmış 190 derecelik fırında altı üstü güzelce kızarana kadar pişiriniz.",
        "6. Soğuduktan sonra pidenizi küp küp doğrayınız 1 yemek kaşığı tereyağını tavaya koyup eritiniz sonra kesmiş olduğunuz pideleri tavanın içine koyup 4-5 dakika kızartp kenara alınız .",
        "7. Daha sonra dönerin hazırlamak için soğanı rendeleyiniz, uygun bir kabın içine kıymayı, rendelenmiş soğanı, yoğurdu ve baharatları ekleyip güzelce yoğurunuz .",
        "8. Sonra 4 parçaya bölünüz, her birini iki yağlı kağıt arasına alıp yağlı kâğıt büyüklüğünde merdaneyle açınız.",
        "9. Fırın tepsisine yağlı kağıt serip üzerine yerleştiriniz yanına servis için domates ve yeşil biber eköyüp önceden ısıtılmış 200 derecelik fırında 30 dakika pişiriniz.",
        "10. İskender’in sosu için sarımsakları eziniz pişirme kabınızın içine tereyağını koyup erritiniz sonra sonra domates sosunu, sarımsakları tuzu ve ketçaplı köyünüz en son suyu ilave edip kaynatınız diğer yanda küçük bir tavanın içine tereyağını koyup eritiniz.",
        "11. Sonra servis için tabağa önce pideleri köyünüz onun üzerine yapmış olduğunuz sosu dökünüz yanına domates ve biberleri koyunuz ,yoğurduda ekleyip dönerleri pidenin üzerine koyunuz üzerine bolca tereyağı gezdirip afiyetle tüketiniz."
    ],
    chefTip: "Viral Olan Ev Yapımı Kıyma Döner İle İskender Tarifim hazırlarken malzemelerin taze olması ve pişerken kısık ateşte demlenmesi lezzeti iki katına çıkarır! 💡",
