  Recipe(
    id: "r_87",
    title: "Havuçlu Rulo Salata",
    emoji: "🥗",
    imageUrl: "https://i.nefisyemektarifleri.com/2025/07/16/havuclu-rulo-salata.jpg",
    prepTimeMinutes: 35,
    difficultyStars: 2,
    calories: 107,
    mealType: MealTypeFilter.mainCourse,
    ingredientsText: ["• 1 kg havuç", "• Yarım su bardağı su", "• 3 yumurta", "• 1 su bardağı un", "• Tuz", "• İç harcı için:", "• 400 gram labne peyniri", "• 2 yemek kaşığı mayonez", "• Yarım demet kıyılmış dereotu", "• Ufak bir kase konserve mısır", "• Ufak bir kase doğranmış kornişon turşu", "• (dilerseniz kornişon yerine zeytin veya salam da doğrayabilirsiniz)"],
    requiredIngredients: [getIng('beyaz_peynir'), getIng('dereotu'), getIng('havuc'), getIng('labne'), getIng('misir'), getIng('tuz'), getIng('un'), getIng('yumurta')],
    steps: [
        "1. Öncelikle rendelediğimiz havuçları biraz tuz ile suyunu salıp çekene dek ocakta kavuruyoruz.",
        "2. Ardından yarım su bardağı suyu ekleyip suyu çekene dek karıştırarak pişiriyoruz (iyice yumuşayacak). Ardından soğumaya bırakıyoruz.",
        "3. Bu sırada ayrı bir kapta yumurtaların aklarını bir fiske tuz ilavesiyle 3-5 dk köpük köpük olana kadar çırpıyoruz.",
        "4. Yumurtaların sarılarını da havuca ekliyoruz. Üzerine un ve tuzunu da ilave edip blenderdan geçiriyoruz.",
        "5. Köpüren yumurta aklarını da ekleyip çok söndürmeden bir spatula ile karıştırıyoruz.",
        "6. Fırın tepsisine yağlı kağıt serip harcı döküyoruz ve eşit şekilde düzleyerek 170 dereceye önceden ısıttığımız fırında yaklaşık 12-15 dk kadar pişiriyoruz.",
        "7. Fırından çıkarıp sıcak haliyle yağlı kağıt ile birlikte rulo yapıyoruz ve bir havlu ile örtüyoruz.",
        "8. Kenarda soğurken iç harcını hazırlıyoruz. Harç için gerekli tüm malzemeyi karıştırıyoruz. Havuçlu ruloyu tam olarak soğumamış, henüz ılıkken rulosunu açıyoruz.",
        "9. İç harcı üzerine eşit şekilde yayıp yağlı kağıttan ayırarak rulo yapıyoruz bu sefer ve streç film ile kapatıp buzdolabında bekletiyoruz. Bu şekilde 1 gece bekletebiliyoruz veya biraz kendine geldiğinde dilimleyebiliyoruz. Afiyet olsun 😋."
