        "3. Tencereye sıvı yağ ve soğanı ekleyip birkaç dakika kavuralım. Kuşbaşı etleri de ekleyip etler suyunu çekinceye kadar kavuralım. Eğer dana eti kullanacaksanız etleri önceden haşlamanızda fayda var.",
