  Recipe(
    id: "r_105",
    title: "Pide Lezzetinde Soğanlı Tepsi Poğaçası",
    emoji: "🥐",
    imageUrl: "https://i.nefisyemektarifleri.com/2026/01/16/pide-lezzetinde-soganli-tepsi-popacasi.jpg",
    prepTimeMinutes: 35,
    difficultyStars: 2,
    calories: 85,
    mealType: MealTypeFilter.breakfast,
    ingredientsText: ["• Hamuru için;", "• 1 su bardağı ılık su", "• 1 su bardağı ılık süt", "• Yarım su bardağı sıvı yağ", "• 1 paket instant maya", "• 1 yemek kaşığı şeker", "• 1 tatlı kaşığı tuz", "• 4,5 su bardağı kadar un (kontrollü eklenecek)", "• İç harcı için;", "• 4 adet orta boy soğan", "• 1 yemek kaşığı salça", "• Kaşar rendesi", "• Kara biber", "• Pul biber", "• Tuz", "• Üzeri için;", "• 2 yumurta sarısı", "• Susam"],
    requiredIngredients: [getIng('biber'), getIng('kasar'), getIng('pulbiber'), getIng('salca'), getIng('seker'), getIng('siviyag'), getIng('sogan'), getIng('sut'), getIng('tuz'), getIng('un'), getIng('yumurta')],
    steps: [
        "1. Hamuru için un dışındaki tüm malzemeler yoğurma kabına alınıp karıştırılarak kontrollü un eklenerek yoğurulup üzeri kapalı 45 dakika mayalanmaya bırakılır.",
        "2. Hamur mayalanırken ince doğranmış soğanlar tavaya alınıp yağ da ekleyip orta ateş ara ara karıştırarak soğanlar iyice kavrulur.",
        "3. Tuz ve salça eklenip salçanın kokusu çıkıncaya kadar kavurup ocaktan alıp baharatlarını ekleyip karıştırıp soğumaya bırakılır.",
        "4. Mayalanan hamur iki eşit parçaya bölünüp hafif un serptiğimiz tezgahta merdaneyle çok da ince olmayacak şekilde açılıp yağlı kağıt serili tepsiye serilir ve üzerine biraz kaşar rendesi serilir ve soğanlı iç harcı hamurun her yerine gelecek şekilde spatulayla yayılır.",
        "5. Soğanların üzerine de kaşar rendeleyip kalan diğer hamuru da aynı şekilde merdaneyle açıp sermiş olduğumuz iç harcın üzerine serilir ve dilimlenir.",
        "6. Üzerine yumurta sarısı sürüp, susam serpip önceden 200 derece ısıtılmış fırında yaklaşık 40-45 dakika kadar üzeri kızarıncaya kadar pişirilir. Deneyeceklere şimdiden afiyet olsun."
    ],
    chefTip: "Pide Lezzetinde Soğanlı Tepsi Poğaçası hazırlarken malzemelerin taze olması ve pişerken kısık ateşte demlenmesi lezzeti iki katına çıkarır! 💡",
  ),
  Recipe(
    id: "r_106",
    title: "Susamlı Tuzlu Kesme Kurabiye (1 Tepsi Dolusu)",
    emoji: "🧁",
    imageUrl: "https://i.nefisyemektarifleri.com/2020/10/26/susamli-tuzlu-kesme-kurabiye-1-tepsi-dolusu-18.jpg",
    prepTimeMinutes: 65,
    difficultyStars: 3,
    calories: 28,
    mealType: MealTypeFilter.dessert,
    ingredientsText: ["• 250 gram oda sıcaklığında erimiş margarin veya tereyağı", "• 1 yumurta ( sarısı içine akı dışına)", "• 2 yemek kaşığı sıvı yağ", "• 2,5 yemek kaşığı sirke", "• 1 tatlı kaşığı tuz", "• 3 tatlı kaşığı şeker", "• 1 tatlı kaşığı mahlep", "• 1 paket kabartma tozu", "• 3 su bardağı un ( 3.cü bardak kontrollü eklenecek)", "• Üzeri için;", "• Yumurta akı", "• Kavrulmuş susam", "• Çörekotu"],
    requiredIngredients: [getIng('seker'), getIng('siviyag'), getIng('tereyagi'), getIng('tuz'), getIng('un'), getIng('yumurta')],
    steps: [
        "1. Öncelikle yoğurma kabımıza un ve kabartma tozu hariç bütün malzemeleri ekleyip, karıştıralım.",
        "2. Unumuzu ve kabartma tozunu eleyerek kontrollü bir şekilde ekleyip, kulak memesi kıvamında hamurumuzu yoğuralım.",
        "3. Yoğurduğumuz hamurumuzu buzdolabında dinlenmeye bırakıp, bu sırada tavaya susamı ekleyip, sürekli karıştırarak kavuralım.",
        "4. Kavrulan susamı hiç bekletmeden bir kaseye alalım. ( tavada beklerse sıcaklığı ile yanacaktır. )",
        "5. Daha sonra hamurumuzu alıp, yağlı kağıt arasında merdane ile çok ince olmayacak şekilde açalım.",
        "6. Ardından hamurumuzu dikdörtgen olacak şekilde düzgünce keselim. Kenardaki hamurları tekrar yoğurma kabımıza alıp, toparlayalım.",
        "7. Hamurumuzu bıçak ile karelere ayırıp, üzerine yumurta akı sürüp, susam ve çörek otu serpelim, tepsimize aralıklı dizelim.",
        "8. Bütün hamur bitene kadar bu şekilde işleme devam edelim. En son kalan hamurları yuvarlak yapabilirsiniz.",
        "9. Önceden ısıtılmış 180 derece fırında 20 dakika pişirelim.Afiyet olsun. (Fırından fırına süresi değişebilir."
    ],
    chefTip: "Susamlı Tuzlu Kesme Kurabiye (1 Tepsi Dolusu) hazırlarken malzemelerin taze olması ve pişerken kısık ateşte demlenmesi lezzeti iki katına çıkarır! 💡",
  ),
