  Recipe(
    id: "r_111",
    title: "Muz Kızartması Tarifi (videolu)",
    emoji: "🧁",
    imageUrl: "https://i.nefisyemektarifleri.com/2019/12/11/muz-kizartmasi-tarifi.jpg",
    prepTimeMinutes: 20,
    difficultyStars: 1,
    calories: 43,
    mealType: MealTypeFilter.dessert,
    ingredientsText: ["• 4 adet orta boy muz", "• Hamuru için:", "• 1 adet yumurta", "• Yarım su bardağı süt", "• 1 su bardağından biraz az un", "• 1 yemek kaşığı şeker (tepeleme)", "• 1 paket kabartma tozu", "• Yarım çay kaşığı tarçın (isteğe bağlı)", "• Üzeri için (isteğe bağlı kullanılabilir)", "• Bal", "• Dondurma", "• Tarçın", "• Pudra Şekeri", "• Kızartmak için:", "• Sıvı yağ (ayçiçek yağı kullandım)"],
    requiredIngredients: [getIng('seker'), getIng('siviyag'), getIng('sut'), getIng('un'), getIng('yumurta')],
    steps: [
        "1. Muz Kızartmasının hamuru için ilk olarak yumurta ve şekeri çırpma kabımıza alalım. Tel çırpıcı ile şekerler eriyene kadar çırpalım.",
        "2. Daha sonra süt, un ve kabartma tozunu ilave edelim ve hamuru karıştıralım. Dilerseniz tarçını bu aşamada ekleyebilirsiniz. Ben sonradan üzerine serptim ama hamuruna daha çok yakıştığını düşünüyorum. Hamurun kıvamı çok akışkan ya da çok katı olmayacak. Videoda da göreceğiniz kıvam yeterli oluyor. Verdiğim ölçülerde hazırladığınızda sorun yaşamayacaksınız ;)",
        "3. Kızartmak için küçük bir tencereye sıvı yağımızı alarak ısıtalım. Bol yağda kızardığı için küçük bir tencere kullanmayı tercih ediyorum ;)",
        "4. Son olarak muzlarımızın kabuklarını soyarak istediğimiz boyutta dilimleyelim. Bu kısmı sona bırakmamızın nedeni muzları önce soyduğunuzda beklerken kararacaktır. Bu nedenle sona bırakmanızı öneririm.",
        "5. Sıra geldi en keyifli kısma yani pişirmeye ;) Muz parçalarını hamura bulayarak kızgın yağa bırakalım. Ben hamura bulama kısmında minik şişleri kullandım ama muzu hamurun içesine bırakıp çatalla çevirerek her yerinin bulanmasını sağlayabilirsiniz. Hangisi kolayınıza gelirse :)Hamurunuz çok akışkan ise çok az un ekleyebilir, çok katı ise 1-2 kaşık süt ekleyerek kıvamını ayarlayabilirsiniz. Videodaki kıvam size yardımcı olacaktır.",
        "6. Muzları kızartırken her yerinin eşit şekilde kızarması için çevirmeyi ihmal etmeyelim. Kısa sürede kızaracaklardır. Bu aşamada ocağınızı orta ateşte açabilirsiniz, çok yüksek ateşte pişirmenizi önermem.",
        "7. Güzelce kızaran muzları peçete üzerine çıkartarak fazla yağın süzülmesini sağlayalım.",
        "8. İyice soğuduktan sonra dilediğiniz şekilde servis edebilirsiniz. Ben bal ve tarçın ile servis ettim. Eğer tarçını hamurun içerisinde kullanmışsanız üzerine ayrıca serpmenize hiç gerek yok."
    ],
    chefTip: "Muz Kızartması Tarifi (videolu) hazırlarken malzemelerin taze olması ve pişerken kısık ateşte demlenmesi lezzeti iki katına çıkarır! 💡",
  ),
