    requiredIngredients: [getIng('biber'), getIng('bulgur'), getIng('domates'), getIng('irmik'), getIng('karabiber'), getIng('maydanoz'), getIng('pulbiber'), getIng('salca'), getIng('sarimsak'), getIng('tuz'), getIng('un'), getIng('yogurt'), getIng('yumurta'), getIng('zeytinyagi')],
    steps: [
