    ingredientsText: ["• 2 adet tavuk but", "• 1 yemek kaşığı tereyağı", "• 2 yemek kaşığı sıvı yağ", "• 6 diş karanfil", "• 6 diş kakule", "• 2 adet defne yaprağı", "• 1 adet çubuk tarçın", "• Yarım yemek kaşığı domates salçası", "• 3 su bardağı su", "• Sosu için;", "• 1 adet soğan", "• 1 adet domates", "• 1 tatlı kaşığı tuz", "• Yarım çay kaşığı karabiber", "• 1 çay kaşığı zerdeçal", "• Yarım çay kaşığı kuru kişniş", "• Yarım yemek kaşığı üzüm sirkesi", "• Pilav İçin;", "• Yarım yemek kaşığı tereyağı", "• 1 yemek kaşığı sıvı yağı", "• Yer fıstığı, dolmalık fıstık ve kaju", "• 2 su bardağı yasemin pirinci"],
    requiredIngredients: [getIng('biber'), getIng('domates'), getIng('fistik'), getIng('karabiber'), getIng('salca'), getIng('siviyag'), getIng('sogan'), getIng('tavuk'), getIng('tereyagi'), getIng('tuz')],
    steps: [
        "1. Uygun bir kase içerisine rendelenmiş soğan, domates, tuz, karabiber, zerdeçal, kişniş ve sirkeyi alarak güzel bir şekilde karıştıralım.",
        "2. Tavuk butlarımızı hazırladığımız sosun içerisine koyarak güzel bir şekilde harmanlayalım.",
        "3. Daha sonra tavuklarımızı bir kaba yerleştirerek geriye kalan sosu üzerlerine dökelim ve kabımızın üzerini streçleyelim, yarım saat kadar buzdolabında dinlenmeye bırakalım.",
        "4. Ocağa aldığımız uygun bir tencerenin içerisine tereyağı ve sıvı yağı alalım, tereyağı eridikten sonra içerine karanfil ve kakuleyi ekleyerek karıştıralım.",
        "5. Sonrasında defne yaprağı, tarçını ve salçayı ekleyerek tekrar karıştıralım.",
        "6. Tavuklarımızı da tencereye alarak kalan sosu da üzerlerine dökelim.",
        "7. Son olarak suyu da ekleyelim ve tencerenin kapağını kapatarak pişmeye bırakalım.",
        "8. Pişen tavuklarımızı fırın kabına alalım ve önceden 180°C fırında üzerleri kızarana kadar pişirelim. Pilavı yaparken kullanacağımız için tavukları pişirdiğimiz soslu suyu dökmeyelim.",
        "9. Pilav için uygun bir tencereye tereyağı ve sıvı yağı alalım.",
        "10. Yer fıtığı, dolmalık fıstık ve kajuyu ekleyerek güzelce kavuralım.",
        "11. Daha yıkadığımız yasemin pirincini ekleyelim ve karıştıralım.",
        "12. Son olarak tavukları pişirdiğimiz suyu da süzerek ekleyelim ve tenceremizin kapağını kapatarak, pirnçler suyunu çekene kadar pişmeye bırakalım.",
        "13. Suyunu çekip pişen pilavımızı ocaktan alalım ve üzerine kağıt havlu kapatıp, kapağını kapatarak 10-15 dakika kadar demlenmeye bırakalım.",
        "14. Güzelce demlenen pilavımızı karıştıralım ve servis tabağımıza alalım.",
        "15. Üzerine fırından aldığımız tavuk butlarını yerleştirdikten sonra yemeye hazır. Deneyeceklere afiyet olsun."
