        "4. Beşamel sosunu hazırlıyoruz. Tereyağ ve unu kavuruyoruz azar, azar sütü ilave ederek kıvam alana kadar kaynatıyoruz bir fiske tuz ve karabiber ilave edip ocağı kapatıyoruz.",
