        "3. Toz Antep fıstığını rondoda çekerek karışıma ilave edin. Bu şekilde hem aroması hem rengi güçlenecektir.",
        "4. Karışıma son olarak kalan tüm kuru malzemeleri (un, mısır nişastası, kabartma tozu, vanilya ve tuz) ekleyerek güzelce karıştırın. Unun önce yarısını sonra kalan yarısını eklemenizi tavsiye ederim, bu sayede kıvamını daha kolay ayarlayabilirsiniz. Çok katı olmayan bir hamur elde etmelisiniz.",
        "5. İri iri doğranmış çikolataları da hamura ekledikten sonra son bir kez karıştırın. Dilerseniz bu aşamada pirinç Antep fıstık da ekleyebilirsiniz hamura ya da benim gibi üzerlerine serpiştirebilirsiniz.",
        "6. Elde ettiğiniz hamuru 15-20 dk kadar buzdolabında bekletin.",
        "7. Süre sonunda hamuru top top şekillendirerek yağlı kağıt serdiğiniz tepsiye ya da yapışmaz bir tepsiye dizin. Üzerlerine pirinç Antep fıstığı serpin.",
        "8. Önceden ısıttığınız 200 derece fırında 10 dakika pişirin. Son 5 dakikada fanlı ayarı kullanabilirsiniz.",
        "9. Fırından çıkarında 5-10 dakika kadar soğumalarını bekleyin, kırılgan ve yumuşak olacaklar ve soğudukça biraz daha sertleşecekler.",
        "10. Afiyet olsun."
    ],
    chefTip: "Antep Fıstıklı Levain Kurabiye hazırlarken malzemelerin taze olması ve pişerken kısık ateşte demlenmesi lezzeti iki katına çıkarır! 💡",
  ),
  Recipe(
    id: "r_133",
    title: "Kızarmış Dondurma Tarifi (videolu)",
    emoji: "🧁",
    imageUrl: "https://i.nefisyemektarifleri.com/2021/06/30/kizarmis-dondurma-tarifi.jpg",
    prepTimeMinutes: 10,
    difficultyStars: 1,
    calories: 8,
    mealType: MealTypeFilter.dessert,
    ingredientsText: ["• 380 gram dondurma", "• 2 adet yumurta akı", "• 1 kase cornflakes", "• 1 tatlı kaşığı tarçın", "• Kızartmak için;", "• Sıvı yağ"],
    requiredIngredients: [getIng('siviyag'), getIng('yumurta')],
    steps: [
        "1. Maraş dondurmamızı tezgaha alıp 6 eşit parçaya bölelim. Özellikle sert bir dondurma tercih ediyorum, kızartma işlemi için kesme maraş dondurması kullanmanız daha uygun olacaktır.",
        "2. Tezgaha streç filmimizden bir parça keselim. Streç film sayesinde dondurmalarımızı kolayca yuvarlayıp top şeklini verebileceğiz.",
        "3. Kestiğimiz dondurma parçalarından birini streçe yerleştirip üstünü sarıp elimizle bastırıp yuvarlayarak top şeklini verelim.",
        "4. Tüm dondurma parçalarını aynı şekilde streç filmimize sarıp şekillendirmeye devam edelim.",
        "5. Dondurmalarımızın üstünü kaplamadan önce şeklinin bozulmaması için 1 saat kadar dondurucuda dinlendirelim.",
        "6. Dondurmamızın kaplaması için çift kilitli poşetimizi alalım. İçerisine 1 kase kadar kahvaltılık mısır gevreğini dökelim. Çift kilidini kapatalım ve bir merdane yardımı ile gevrekleri ezelim. Gevrekleri un gibi ezmiyoruz biraz taneli olacak şekilde bırakıyoruz.",
        "7. Ezdiğimiz gevreklerimizi tabağımıza alalım üzerine 1 tatlı kaşığı tarçın ekleyip karıştıralım.",
        "8. Buzdolabından çıkardığımız dondurmalarımızı streç filminden çıkarıp her yerini yumurta akına bulayalım. Ardından tüm yüzeyini mısır gevreği ile kaplayalım.",
        "9. Sonra dondurmamızı tekrar streç filmin içerisine koyup etrafını sarıp sıkıca kapatalım.",
        "10. Tüm dondurmalarımızı aynı şekilde önce yumurta akına daha sonra tarçınlı mısır gevreğine bulayalım.",
        "11. Streç film ile sarıp kapattığımız dondurmaların üzerinin daha kalın bir katman olması için 1 kat daha kaplayacağım. Son kaplama işlemi öncesinde dondurmaları yine 1 saat dondurucuda dinlenmeye bırakalım.",
        "12. Dinlendirdiğimiz dondurmalarımızın son katmanı için yine önce yumurta akına daha sonra ise tarçınlı mısır gevreğine bulayarak yüzeyini tamamen kaplayalım.",
        "13. Dondurma tamamen gevreğin içinde kalmalı üzerinde açık bir yer bırakırsanız dondurmanız yağa temas ettiğinde hemen eriyecektir.",
        "14. Kapladığımız dondurmalarımızı fermuarlı poşetimize dizelim ve kızartmadan önce en az 1-2 saat daha dondurucuda dinlenmeye bırakalım.",
        "15. Dinlenen dondurmaları kızdırdığımız yağın içerisine bırakalım çevirerek 1-2 dakikada hemen rengi dönünce alalım. Kızgın yağ olduğu için üzeri hemen kızaracaktır içindeki dondurmanın erimemesi için bu aşamada hızlı olmaya dikkat edelim",
        "16. Kızaran dondurmaları çikolata sosu yada mevsim meyveleri ile sıcak sıcak servis edebilirsiniz.",
        "17. Önceden hazırlayıp fermuarlı poşetle saklayarak misafiriniz geldiğinde 1-2 dk içinde hemen ikram edebilirsiniz."
    ],
    chefTip: "Kızarmış Dondurma Tarifi (videolu) hazırlarken malzemelerin taze olması ve pişerken kısık ateşte demlenmesi lezzeti iki katına çıkarır! 💡",
  ),
  Recipe(
