        "2. Ardından ocağa alıyoruz, orta ateşte sürekli karıştırarak kaynamaya başlayıncaya kadar pişiriyoruz ( dibinin tutmaması ve kıvamının güzel olması için ocağın başından ayrılmadan sürekli karıştırıyoruz!)",
        "3. Kaynamaya başlayınca ocaktan alıp 1 yemek kaşığı tereyağı 1 paket vanilya ve aroma katmak istiyorsak,tercihen portakal ya da limon kabuğu rendesi ekleyerek hızlıca karıştırıyoruz.",
