        "5. Spatulayla düzeltip oda sıcaklığında soğuması için bekletiyoruz .",
        "6. Soğuduktan sonra hindistan cevizi ve tarçını karıştırıp tatlımızın üzerine serpiyoruz buzdolabında 1-2 saat dinlendirip servis ediyoruz."
    ],
    chefTip: "1 Bardak İrmikle Kolay Ve Lezzetli Sütlü Tatlı (Videolu) hazırlarken malzemelerin taze olması ve pişerken kısık ateşte demlenmesi lezzeti iki katına çıkarır! 💡",
