        "4. Ocağa su koyup kaynatınız ,kaynayan suya yapmış olduğunuz köfteleri atıp 7-8 dakika haşlayınız.",
        "5. Diğer yanda uygun bir tavada tereyağını etiğiniz içine salçayı ve kuru naneyi ekleyip salçanın kokusu çıkana kadar kavurunuz.",
        "6. Haşlanan köftelere salçalı sosu döküp karıştırınız.",
        "7. Sonra bir kase yoğurda 2 dış sarımsak eziniz ve tuz ekleyiniz güzelce karıştırıp köftelerin üzerine yayınız.",
        "8. Üstüne yarım yemek kaşığı tereyağını eritip içine bir çay kaşığı kırmızı biber koyup karıştırın yoğurdun üstüne dökünüz, en son maydanozla süsleyip servis yapınız."
