    ingredientsText: ["• 2 su bardağı yoğurt", "• 1 bağ semizotu", "• 1 adet salatalık", "• 1 çay kaşığı tuz", "• 1 yemek kaşığı kuru nane (tercihe bağlı)", "• 1 diş dövülmüş sarımsak (isteğe bağlı)"],
