    requiredIngredients: [getIng('biber'), getIng('bulgur'), getIng('ceviz'), getIng('domates'), getIng('karabiber'), getIng('nane'), getIng('salca'), getIng('sarimsak'), getIng('sogan'), getIng('tuz')],
