  Recipe(
    id: "r_155",
    title: "Patatesli Börek Tadında Pratik Kahvaltılık (Videolu)",
    emoji: "🥐",
    imageUrl: "https://i.nefisyemektarifleri.com/2025/02/19/patatesli-borek-tadinda-pratik-kahvaltilik-videolu.jpg",
    prepTimeMinutes: 50,
    difficultyStars: 3,
    calories: 16,
    mealType: MealTypeFilter.breakfast,
    ingredientsText: ["• 500 gram patates", "• 3 adet yumurta ( büyükse 2 adet kullanabilirsiniz )", "• 2 su bardağı süt", "• 3 yemek kaşığı sıvı yağ", "• 2 çay kaşığı tuz", "• 1,5 su bardağı un", "• Bir avuç ince kıyılmış dereotu", "• Bir avuç ince kıyılmış maydanoz", "• Pişirmek için :", "• Biraz sıvı yağ"],
    requiredIngredients: [getIng('dereotu'), getIng('maydanoz'), getIng('patates'), getIng('siviyag'), getIng('sut'), getIng('tuz'), getIng('un'), getIng('yumurta')],
    steps: [
        "1. Patateslerin kabuklarını soyduktan sonra küp küp doğrayarak uygun bir kaba alıyoruz .",
        "2. Üzerine yumurta ve süt ekliyerek blendırla patatesleri eziyoruz ( patatesler hafif pütürlü kalabilir,uzun süre ezmenize gerek yok)",
        "3. Tuz,sıvı yağ ve un ekleyerek mikserle güzelce çırpıyoruz ( harcım kıvamı,ne çok akışkan ne de çok katı olmamalı)",
        "4. Son olarak maydanoz ve dereotu ekleyerek karıştırıyoruz.",
        "5. Krep tavasına 1 çay kaşığı kadar sıvı yağ serperek tavayı kızdırıyoruz ,hemen ardından hazırlamış olduğumuz harçtan 1-2 kepçe kadar tavaya alarak tavayı elimizde hafifçe sallayarak harcı dağıtıyoruz .",
        "6. Orta ateşte altı hafif kızarıncaya kadar pişiriyoruz ,dikkatlice ters çevirip diğer tarafıda pişirdikten sonra tavadan alıyoruz ,sıcak sıcak tüketiyoruz 👌🙂"
    ],
    chefTip: "Patatesli Börek Tadında Pratik Kahvaltılık (Videolu) hazırlarken malzemelerin taze olması ve pişerken kısık ateşte demlenmesi lezzeti iki katına çıkarır! 💡",
  ),
  Recipe(
    id: "r_156",
    title: "Avusturya’nın Meşhur Kral Tatlısı: Kaiserschmarrn Tarifi",
    emoji: "🧁",
    imageUrl: "https://i.nefisyemektarifleri.com/2023/07/27/avusturyanin-meshur-kral-tatlisi-kaiserschmarrn-tarifi-1.jpg",
    prepTimeMinutes: 45,
    difficultyStars: 3,
    calories: 13,
    mealType: MealTypeFilter.dessert,
    ingredientsText: ["• 4 yumurta", "• 3 yemek kaşığı şeker", "• 1 paket vanilin şekeri", "• 400 ml süt (2 su bardağı)", "• 200 gram un (yaklaşık 1,5 su bardağı)", "• 1 avuç dolusu kuru üzüm", "• 1 tutam tuz", "• 1 yemek kaşığı tereyağı", "• Servis için;", "• Pudra şekeri"],
    requiredIngredients: [getIng('seker'), getIng('sut'), getIng('tereyagi'), getIng('tuz'), getIng('un'), getIng('yumurta')],
    steps: [
        "1. Geniş 2 adet kaseye yumurtaların sarıları ile beyazlarını ayırın.",
        "2. Yumurta sarılarına şekerin yarısını ve vanilyayı ilave edip çırpın.",
        "3. Sütü ekleyerek çırpmaya devam edin.",
        "4. Son olarak unu ekleyin ve pürüzsüz bir kıvam alana kadar karıştırın.",
        "5. Yumurta beyazlarına kalan şeker ve bir tutam da tuz ekleyerek mikser yardımıyla güzelce çırpın.",
        "6. Çırptığınız yumurta beyazından birkaç kaşık alarak hazırladığınız diğer hamura ekleyin. Söndürmeden katlaya katlaya karıştırın.",
        "7. Daha sonra bu karışımı, kalan yumurta beyazı karışımının üzerine dökün ve yine dikkatlice, katlaya katlaya karıştırın.",
        "8. Yapışmaz geniş bir tavaya ocağa alın. Orta ateşte ısıtın. (Ben 5 kullandım, benim ocağımda maksimum ayar 9. )",
        "9. Tereyağını ekleyerek eriyip biraz da ısınmasını bekleyin.",
        "10. Hamuru tavaya dökün, 2-3 dakika geçtikten sonra isteğe göre kuru üzüm serpiştirin.",
        "11. Ara sıra altını kontrol ederek pişirin. Piştikçe tavanın kenarlarından ayrılmaya başlayacaktır. Bu şekilde kenar kısımlarından spatula yardımı ile kaldırıp altının durumunu kontrol edebilirsiniz. Yeterince kızardığı zaman çevirip diğer yüzünü pişirin.",
        "12. Kolayca çevirebilmek için bu dev pankeki 4’e bölün ve her bir parçayı ayrı ayrı ters çevirin. Sonrasında zaten parçalayarak servis edeceğiniz için bu noktada aşırı simetrik ve özenli olmanıza gerek yok. :)",
        "13. Ters çevirdikten sonra diğer yüzeyinin de kızarmasını bekleyin. Her iki yüzeyi de güzelce kızardığında çatal yardımıyla pankeki parçalara ayırın.",
        "14. Parçalanan pankeklerin üzerine pudra şekeri gezdirin. (ben biraz normal şeker de serpiyorum). Şekerler eriyip karamelize olana kadar ara sıra pankekleri karıştırarak bir nevi soteleyin.",
        "15. Servis tabağına alarak, yanında dilediğiniz reçel, marmelat, sürülebilir çikolata, fındık-fıstık ezmesi, bal vs. ile servis edin. Afiyet olsun."
    ],
    chefTip: "Avusturya’nın Meşhur Kral Tatlısı: Kaiserschmarrn Tarifi hazırlarken malzemelerin taze olması ve pişerken kısık ateşte demlenmesi lezzeti iki katına çıkarır! 💡",
  ),
