  Recipe(
    id: "r_161",
    title: "Çiğ Köfte (25 Yıllık Tecrübe İle)",
    emoji: "🥗",
    imageUrl: "https://i.nefisyemektarifleri.com/2025/04/04/cig-kofte-25-yillik-tecrube-ile.jpg",
    prepTimeMinutes: 30,
    difficultyStars: 2,
    calories: 114,
    mealType: MealTypeFilter.mainCourse,
    ingredientsText: ["• 500 gram esmer ince bulgur ( mümkünse aktardan alınsın)", "• 1 çay bardağı isot", "• 1 çay bardağı zeytinyağı", "• 3-4 diş sarımsak", "• 1 orta boy kuru soğan", "• 2 orta boy domates rendelenmiş", "• 4 yemek kaşığı domates salçası", "• 2 adet limon", "• 2 yemek kaşığı nar ekşisi", "• 1/2 (yarım) yemek kaşığı köfte baharatı", "• 1/2 (yarım) tatlı kaşığı kuru nane", "• 1/2 (yarım) tatlı kaşığı kekik", "• 1 tatlı kaşığı tuz", "• 1/2 (yarım) demet maydanoz ince kıyılmış", "• 3-4 dal yeşil soğan ince kıyılmış", "• 1 adet salatalık", "• Süsleme için;", "• 1 demet tere", "• 1 demet roka", "• 1 adet göbek marul veya kıvırcık"],
    requiredIngredients: [getIng('bulgur'), getIng('domates'), getIng('kekik'), getIng('limon'), getIng('marul'), getIng('maydanoz'), getIng('nane'), getIng('salatalik'), getIng('salca'), getIng('sarimsak'), getIng('sogan'), getIng('tuz'), getIng('zeytinyagi')],
    steps: [
        "1. Çiğ köfteyi yoğurmadan önce, çiğ köfte tepsisi ile tüm çiğ köftelik malzemeleri hazırlayalım.",
        "2. Öncelikle çiğ köfte için kullanılacak sosu hazırlayalım. Sosun içine konulacak isotu bir kaseye koyup üzerine zeytinyağını ekleyelim.",
        "3. İsot zeytinyağ ile yumuşarken; salça, tuz, baharatlar, nar ekşisi, bir adet limon suyu ve kenarda bekleyen isot bir kaba konularak karıştırılır.",
        "4. Maydanozların yaprakları saplarından ayrılarak ince ince kıyılır, yeşil soğan da ince ince kıyılır. Marul ve diğer yeşillikler güzelce yıkanarak hazırlanır.",
        "5. Çiğ köfte tepsisine esmer ince bulgur dökülür, üzerine rendelenmiş sarımsak, rendelenmiş kuru soğan suyla yıkandıktan sonra tepsiye eklenir.",
        "6. Önce bulgur sarımsak ve soğan ile beraber 5-10 dakika yoğurulur. Sonrasında hazırladığımız sos 2-3 defa da eklenerek yoğurulmaya devam edilir. Ara ara gerekirse çiğ köfteye domates sosu eklenir.",
        "7. 30-40 dakika kadar veya bulgur yumuşayınca ince kıyılmış maydanoz ve yeşil soğan üzerine katılarak 10 dakika kadar daha yoğurulur.",
        "8. Hazır olan çiğ köfte bir kaba konularak buzdolabında 1-2 saat dinlendirilir. Sonrasında ceviz büyüklüğünde ele alınarak avuç içinde sıkılarak; marul, salatalık, tere, roka ve limon ile beraber bir tabakta servis edilir. Afiyet olsun."
    ],
    chefTip: "Çiğ Köfte (25 Yıllık Tecrübe İle) hazırlarken malzemelerin taze olması ve pişerken kısık ateşte demlenmesi lezzeti iki katına çıkarır! 💡",
  ),
  Recipe(
    id: "r_162",
    title: "Ispanaklı Kek Pasta (Hiç Ispanak Kokusu Yok)",
    emoji: "🧁",
    imageUrl: "https://i.nefisyemektarifleri.com/2018/01/23/ispanakli-kek-pastahic-ispanak-kokusu-yok.jpeg",
    prepTimeMinutes: 45,
    difficultyStars: 3,
    calories: 45,
    mealType: MealTypeFilter.dessert,
    ingredientsText: ["• 1 su bardağı haşlanmış ve püre haline getirilmiş ıspanak (Sadece yapraklarını kullanın ıspanağın)", "• 1 su bardağı sıvı yağ (200 ml)", "• 1 su bardağı toz şeker (200 ml lik su bardağı ile)", "• 3 yumurta", "• 2 paket vanilya", "• 1 paket kabartma tozu", "• 1, 5 su bardağı un (200 ml su bardağı ile)", "• Kreması için;", "• 500 gr süt", "• 1 yemek kaşığı un", "• 2 yemek kaşığı nişasta", "• 4 yemek kaşığı toz şeker", "• 1 paket vanilya", "• 100 ml sıvı krema", "• Yarım su bardağı beyaz damla çikolata (Bulamazsanız damla çikolata ve kremayı kullanmayabilirsiniz)", "• 1 paket toz krem şanti"],
    requiredIngredients: [getIng('cikolata'), getIng('ispanak'), getIng('krema'), getIng('nisasta'), getIng('seker'), getIng('siviyag'), getIng('sut'), getIng('un'), getIng('vanilya'), getIng('yumurta')],
    steps: [
        "1. Ispanağın sadece yapraklarını doğrayın ve 2 su bardağı kadar suda haşlayın, süzgeçle sudan alıp rondoda iyice püre haline gelip pürüzsüz bir hal alana kadar çekin.",
        "2. Önce yumurtalar ve şeker ve vanilyayı derin bir çırpma kabına alıp iyice kabarana kadar 2 dakika kadar güzelce çırpın.",
        "3. Sıvı yağı ekleyin yine çırpın, ardından un ve kabartma tozunu da ekleyip 2 dakika daha çırpın.",
        "4. En son püre halindeki ıspanağı da ilave edip iyice hamura karışana kadar çırpıp yağladığınız kelepçeli bir fırın kabına ya da borcama dökün",
        "5. 170 derece önceden ısıttığınız fırında ilk 20 dakika hiç açmadan sonrasında da ortasına kürdan batırarak kontrol edip pişirin ve kekin soğuması için kenara alın.",
        "6. Sütün içine un, nişasta, toz şeker ve vanilyayı ekleyin ve iyice çırpın, ocağa alın, sürekli karıştırarak pişirin.",
        "7. 100 ml krema ve damla çikolatayı benmari usülü eritip, pişen kremanın içine ilave edip iyice karıştırın ve kremayı soğuk su dolu bir kabın üstüne oturtup sürekli karıştırarak kabuk tutmadan soğumasını sağlayın.",
        "8. Soğuyan kremanın içine 1 paket toz krem şantiyi de ilave edip iyice çırptınız mı kremamız hazır.",
        "9. Soğuyan keki ortadan ikiye kesin, aradan incecik bir bölüm daha kesin ve bunu rondoda iyice çekin(bu bölümü rondoda çekip süslemesi için ayırıcaz)",
        "10. Kestiğiniz kekin bir tanesini kestiğiniz bölüm üstte kalacak şekilde alıp üzerine hazırladığınız kremadan sürün içine varsa damla çikolata serpin.",
        "11. Diğer kestiğiniz bölümü de üzerine oturtun kalan kremayı kekin üzerine ve yanlarına gelecek şekilde yayın ve rondoda çekip un ufak ettiğiniz keki de kremanın üzerini kapatacak şekilde pastanın her yerine serpiştirin.",
        "12. Üzerini de istediğiniz şekilde süsleyin.Ben çok fazla süslemek istemedim çünkü sade bile çok tatlı bir görüntüsü vardı ama siz isterseniz meyvelerle de süsleyebilirsiniz👍🏻Ispanaklı pastamızın macerası budur, mutlaka deneyin derim☺️👋🏻👋🏻"
    ],
    chefTip: "Ispanaklı Kek Pasta (Hiç Ispanak Kokusu Yok) hazırlarken malzemelerin taze olması ve pişerken kısık ateşte demlenmesi lezzeti iki katına çıkarır! 💡",
  ),
