        "11. Islanmış kekimizin üst kısmı ele yapışmayan bir kuruluğa gelince soğumuş muhallebimizi üzerine ekleyelim.",
        "12. Tatlımızı oda sıcaklığına gelene kadar dışarıda bekletelim. Bu sırada benmari usulü 140 ml sıvı kremayı ısıtıp üzerine beyaz çikolatayı alalım. Tamamen eriyen beyaz çikolatalı ganajımızın ılınmasını bekleyelim.",
        "13. Ilınan ganajı muhallebi üzerine ekleyelim. Üst kısmına yılan gibi sağdan sola topping çikolata sosla geçelim. Bir kürdan yardımı ile aşağıdan yukarıya çikolata topping sosu çekip şekil verelim.",
