    title: "Çilekli Kremalı Pasta (Videolu)",
    emoji: "🧁",
    imageUrl: "https://i.nefisyemektarifleri.com/2026/04/12/cilekli-kremali-pasta-videolu.jpg",
    prepTimeMinutes: 45,
    difficultyStars: 3,
    calories: 20,
    mealType: MealTypeFilter.dessert,
    ingredientsText: ["• Pasta tabanı için:", "• 2 adet büyük boy yumurta", "• 120 gram toz şeker", "• 1 paket vanilya şekeri", "• 70 ml sıvı yağı", "• 80 ml süt", "• 150 gram un", "• 2 silme tatlı kaşığı kabartma tozu", "• Vanilyalı kreması için:", "• 400 ml soğuk sıvı krema", "• 250 gram labne (yağ oranı )", "• 2 poşet krema sertleştirici", "• 4 yemek kaşığı pudra şekeri (70 gr.)", "• 1 vanilya çubuğu", "• Üstü için:", "• 600 gram taze çilek", "• 1 paket çilekli pasta jölesi", "• 250 ml su", "• 1 yemek kaşığı şeker"],
    requiredIngredients: [getIng('krema'), getIng('labne'), getIng('seker'), getIng('siviyag'), getIng('sut'), getIng('un'), getIng('vanilya'), getIng('yumurta')],
    steps: [
        "1. Pastanın tabanı için; yumurtaları şeker ve vanilya şekeri ile mikserde 5 dakika çırpın. Yağ ve sütü ekleyip kısa çırpın.",
        "2. Un ve kabartma tozunu ekleyip 1 dakika çırptıktan sonra hamuru pişirme kağıdı serilmiş dikdörtgen bir kelepçeli kalıba dökün ve önceden 180 derece ısıtılmış fırında üst/alt ısıda 25 dakika pişirin. Pişirdikten sonra kek tabanını tamamen soğumaya bırakın.",
        "3. Vanilyalı krema için kremayı, krem sertleştiriciyi ve pudra şekerini bir kaseye karıştırma kanına alın ve kıvam alana kadar çırpın.",
        "4. Vanilya çubuğunu ikiye bölün ve içini kazıyın. Labne ile birlikte kremaya ekleyin ve kısa çırpın. Vanilyalı kremayı soğumuş pasta tabanın üzerine düzgünce yayın.",
