        "6. Çilekleri kremanın üzerine koyup ellerinizle hafifçe bastırın.",
        "7. Pasta jölesini su ve şekerle karıştırın, kaynatın ve çileklerin üzerine dökün. Donmasını bekleyin ve ardından pastanızı 3 saat buzdolabında bekletin. Afiyet olsun."
    ],
