    imageUrl: "https://i.nefisyemektarifleri.com/2026/02/26/sehrazat-tatlisi-videolu-4.jpg",
    prepTimeMinutes: 40,
    difficultyStars: 2,
    calories: 49,
    mealType: MealTypeFilter.dessert,
    ingredientsText: ["• Keki için:", "• 2 adet yumurta", "• Yarım su bardağı şeker", "• Yarım su bardağı sıvı yağ", "• 1,5 su bardağı galeta unu", "• 4 yemek kaşığı hindistan cevizi", "• 1 paket kabartma tozu", "• 1 paket vanilya", "• Şerbeti için:", "• 2 su bardağı şeker", "• 2 su bardağı su", "• Kreması için:", "• 1 litre süt", "• Yarım çay bardağı toz şeker", "• 2 yemek kaşığı mısır nişastası", "• 2 yemek kaşığı un (tepeleme)", "• 1 yemek kaşığı tereyağ", "• 40 gram beyaz çikolata", "• 100 ml sıvı krema"],
    requiredIngredients: [getIng('ceviz'), getIng('cikolata'), getIng('krema'), getIng('misir'), getIng('nisasta'), getIng('seker'), getIng('siviyag'), getIng('sut'), getIng('tereyagi'), getIng('un'), getIng('vanilya'), getIng('yumurta')],
    steps: [
        "1. Öncelikle şerbeti tencereye alıp kaynamaya bırakın.",
        "2. Kaynamaya başladıktan sonra altını biraz kısarak yaklaşık 10 dakika orta ateşte kaynatın.",
        "3. Ardından ocaktan alıp ılımaya bırakın.",
        "4. Kek için yumurta ve şekeri mikserle açık renk alıp hacmi artana kadar çırpın.",
        "5. Mikseri bırakıp diğer malzemeleri ekleyin ve spatula ile nazikçe karıştırın.",
        "6. Hazırladığınız karışımı sıkma torbasına alın ve 8–10 adet kaseye paylaştırın.",
        "7. Önceden ısıtılmış 180 derece fırında üzeri kızarana kadar pişirin.",
        "8. Muhallebisi için; beyaz çikolata, tereyağı, vanilya ve sıvı krema hariç diğer malzemeleri tencereye alın.",
        "9. Sürekli karıştırarak koyulaşıp kaynayıncaya kadar pişirin.",
        "10. Ocaktan aldıktan sonra tereyağı, beyaz çikolata ve vanilyayı ekleyip karıştırın.",
        "11. Ilıyınca sıvı kremayı ilave edip mikserle pürüzsüz olana kadar çırpın.",
        "12. Fırından çıkan sıcak keklerin ilk harı çıktıktan sonra şerbeti gezdirin.",
        "13. Şerbetini çeken tatlıların üzerine kremayı paylaştırın.",
        "14. Soğuduktan sonra bolca toz antep fıstığı serpin ve buzdolabına kaldırın.",
        "15. Vaktiniz varsa 1 gece dinlendirin; yoksa en az 4–5 saat sonra servis edebilirsiniz."
    ],
