    title: "Mannele Tarifi (Brioche Adamlar)",
    emoji: "🥗",
    imageUrl: "https://i.nefisyemektarifleri.com/2025/01/23/mannele-tarifi-brioche-adamlar.jpg",
    prepTimeMinutes: 50,
    difficultyStars: 3,
    calories: 10,
    mealType: MealTypeFilter.mainCourse,
    ingredientsText: ["• 500 gram un", "• 250 ml süt", "• 2 yumurta", "• 100 gram toz şeker (yaklaşık 8 yemek kaşığı)", "• 80 gram tereyağı, oda sıcaklığında", "• 20 gram kuru maya (yaklaşık 2 yemek kaşığı)", "• 1 tutam tuz", "• Üzeri için;", "• 1 yumurta sarısı", "• Damla çikolata"],
    requiredIngredients: [getIng('cikolata'), getIng('seker'), getIng('sut'), getIng('tereyagi'), getIng('tuz'), getIng('un'), getIng('yumurta')],
    steps: [
        "1. Öncelikle uygun bir kapta 100 ml sütü (ılık olmalı), kuru mayayı, unun 100 gramını ve şekerin de 1 yemek kaşığı kadarını karıştıralım. Üzerini streç ile kaplayıp mayalanması için bırakalım. Yaklaşık iki katına çıktığında hazır demektir.",
        "2. Geniş bir yoğurma kabına kalan unu alalım. Kalan şekeri ve tuzu ilave edip karıştıralım ve ortasında bir çukur oluşturalım.",
        "3. Oluşturduğumuz çukura yumuşamış tereyağını, yumurtaları ve mayalı karışımı ekleyelim.",
        "4. Yavaş yavaş yoğurmaya başlayıp hamuru toparlayalım. Gerekirse çok az un ilavesi yapabilirsiniz.",
        "5. Hamur toparlanınca kabın üzerini yine streç filmle kapatalım ve sonrasında temiz bir mutfak örtüsüyle de kaplayıp sıcak bir ortamda yaklaşık 1.30 saat bekletelim.",
        "6. Güzelce kabarıp mayası gelen hamuru tezgaha alalım. Havasını alıp şöyle bir toparladıktan sonra 10 eşit parçaya ayırıp her birinden bezeler oluşturalım. Dilerseniz bu aşamada damla çikolataları direkt hamura da ilave edebilirsiniz, ben bir kısmını öyle hazırladım.",
        "7. Her bir bezeyi önce rulo yapar gibi şekillendirelim, sonra bir ucunu hafifçe sıkarak kafasının şeklini almasını sağlayalım. Gövdesi olacak kısma ise elimizle hafifçe bastırarak biraz daha yassı hale getirelim.",
        "8. Hamur kesme aparatı ya da bıçak yardımıyla kol ve bacaklarını da kesip şekillendirelim.",
        "9. Şekil verdiğimiz adamları pişirme kağıdı serdiğimiz fırın tepsisine alalım. Ben 5’er 5’er yerleştirerek 2 ayrı tepside pişirdim.",
        "10. Üzerlerine yumurta sarısı sürerek damla çikolata ile gözlerini, ağzını, istediğimiz şekilde süsleyelim ve 15-20 dakika kadar bekletelim. Dilerseniz damla çikolata yerine kuru üzüm de kullanabilirsiniz, geleneksel olarak bu şekilde de yapılıyor :).",
        "11. Önceden 180 dereceye ısıttığımız fırında güzelce kabarıp kızarıncaya kadar yaklaşık 25-30 dakika pişirelim. Afiyet olsun!."
    ],
    chefTip: "Mannele Tarifi (Brioche Adamlar) hazırlarken malzemelerin taze olması ve pişerken kısık ateşte demlenmesi lezzeti iki katına çıkarır! 💡",
